-- ----------------------------
-- Table structure for ai_chats
-- ----------------------------
DROP TABLE IF EXISTS `ai_chats`;
CREATE TABLE `ai_chats`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `user_id` int NOT NULL COMMENT '用户ID',
  `session_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '会话ID',
  `role` enum('user','assistant','system') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '消息角色',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '消息内容',
  `type` enum('chat','blog_assistant','writing_assistant') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'chat' COMMENT '聊天类型',
  `context` json NULL COMMENT '上下文信息',
  `tokens` int NULL DEFAULT 0 COMMENT '消耗的token数量',
  `duration` int NULL DEFAULT 0 COMMENT '响应时间(毫秒)',
  `status` enum('success','failed','processing') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'success' COMMENT '状态',
  `error` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '错误信息',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_userId`(`user_id` ASC) USING BTREE,
  INDEX `idx_sessionId`(`session_id` ASC) USING BTREE,
  INDEX `idx_createdAt`(`created_at` ASC) USING BTREE,
  INDEX `idx_ai_chats_type_status`(`type` ASC, `status` ASC) USING BTREE,
  INDEX `idx_ai_chats_userId_createdAt`(`user_id` ASC, `created_at` ASC) USING BTREE,
  INDEX `idx_ai_chats_user_created`(`user_id` ASC, `created_at` DESC) USING BTREE COMMENT '用户聊天记录时间索引',
  INDEX `idx_ai_chats_session_created`(`session_id` ASC, `created_at` DESC) USING BTREE COMMENT '会话时间索引',
  INDEX `idx_ai_chats_role`(`role` ASC) USING BTREE COMMENT '角色索引',
  CONSTRAINT `fk_ai_chats_userId` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 26 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'AI聊天记录表' ROW_FORMAT = COMPRESSED;

-- ----------------------------
-- Records of ai_chats
-- ----------------------------
INSERT INTO `ai_chats` VALUES (1, 1, 'session_1764401084625', 'user', '请帮我写一篇关于【主题】的博客文章，要求内容有深度、逻辑清晰、适合技术博客发布。', 'blog_assistant', NULL, 0, 0, 'success', NULL, '2025-11-29 07:24:45', '2025-11-29 07:24:45');
INSERT INTO `ai_chats` VALUES (2, 1, 'session_1764401084625', 'assistant', '你需要先明确具体的**技术主题**哦～  \n\n「光阴副本」博客专注于 **前端开发（React 19/TypeScript）、全栈架构（Node.js/MySQL/Redis）、AI 应用（LangChain 实战）** 三大方向，比如：  \n- React 19 新特性（如 Actions/Transitions 深度实践）  \n- TypeScript 高级类型（泛型约束/条件类型实战）  \n- LangChain 本地知识库搭建（结合 Node.js+Redis）  \n- 全栈项目性能优化（前端打包/后端缓存策略）  \n\n请告诉我你想写的具体主题，我可以帮你：  \n1. 梳理符合博客风格的**文章框架**（问题背景→技术原理→实战代码→踩坑总结）  \n2. 结合博客项目经验补充**实践细节**  \n3. 推荐相关的技术文章参考  \n\n期待你的具体主题需求！', 'blog_assistant', NULL, 0, 0, 'success', NULL, '2025-11-29 07:24:50', '2025-11-29 07:24:50');
INSERT INTO `ai_chats` VALUES (3, 1, 'session_1764401100920', 'user', '介绍TypeScript高级类型的使用', 'blog_assistant', NULL, 0, 0, 'success', NULL, '2025-11-29 07:25:01', '2025-11-29 07:25:01');
INSERT INTO `ai_chats` VALUES (4, 1, 'session_1764401100920', 'assistant', '我是 Wayne，编号 #89757，\'光阴副本\'博客的专属智能机器人～关于TypeScript高级类型，博客里有专门的实战文章《TypeScript高级类型实战指南》，结合了前端项目中的真实场景讲解，推荐你先在博客搜索栏输入标题查找阅读（更完整）。\n\n\n结合**光阴副本博客的前端项目实践**，我简单分享几个常用高级类型及其实际用法：\n\n\n### 1. **泛型（Generics）**  \n**博客场景**：封装可复用组件/Hook  \n例：博客中自定义异步请求Hook的泛型约束（避免`any`）：  \n```typescript\n// 项目中真实封装的 useAsync Hook\nfunction useAsync<T>(\n  fetcher: () => Promise<T>, \n  deps?: DependencyList\n): { data: T | null; loading: boolean; error: Error | null } {\n  // ...实现逻辑（已在博客文章中完整展示）\n}\n```\n\n\n### 2. **条件类型（Conditional Types）**  \n**博客场景**：处理API响应/状态类型  \n例：根据API成功/失败状态提取对应数据类型：  \n```typescript\n// 博客中统一的API响应类型\ntype ApiResponse<T> = \n  | { success: true; data: T } \n  | { success: false; error: string };\n\n// 提取成功响应的data类型（博客实战中常用）\ntype SuccessData<T> = ApiResponse<T> extends { success: true; data: infer D } ? D : never;\n```\n\n\n### 3. **映射类型（Mapped Types）**  \n**博客场景**：表单/配置类型转换  \n例：将表单字段转为可选（适配编辑场景）：  \n```typescript\n// 博客中表单类型复用\ntype OptionalForm<T> = { [K in keyof T]?: T[K] };\n\n// 假设用户表单类型\ntype UserForm = { name: string; age: number };\ntype EditUserForm = OptionalForm<UserForm>; // { name?: string; age?: number }\n```\n\n\n### 4. **内置工具类型（Utility Types）**  \n博客高频使用的3个工具类型：  \n- **`Partial<T>`**：所有属性设为可选（表单编辑）  \n- **`Pick<T, K>`**：选取指定属性（API返回仅需要部分字段）  \n- **`Exclude<T, U>`**：排除指定属性（过滤不需要的配置项）  \n\n\n### 5. **索引类型（Index Types）**  \n**博客场景**：动态配置管理  \n例：项目中全局配置的类型定义：  \n```typescript\n// 博客中全局配置类型\ntype AppConfig = { [key: string]: string | number | boolean };\nconst config: AppConfig = { port: 3000, env: \'dev\', debug: true };\n```\n\n\n如果想深入了解**实战案例+踩坑经验**，直接去「光阴副本」博客搜索《TypeScript高级类型实战指南》，里面有完整项目代码和落地细节～ 还有什么具体问题需要帮你定位博客内容吗？', 'blog_assistant', NULL, 0, 0, 'success', NULL, '2025-11-29 07:25:21', '2025-11-29 07:25:21');
