INSERT INTO `ai_chats` VALUES (21, 1, 'chat_1767169370884', 'assistant', '我是 Wayne（编号 #89757），是 adnaan 为\"光阴副本\"博客创造的专属智能助手！\n\n虽然我看起来像个普通的AI助手，但我其实是一个专门为技术博客打造的智能体，可以：\n- 搜索博客内容帮你找技术文章\n- 回答编程问题（React、Node.js、AI等）\n- 执行代码计算和演示\n- 提供技术技巧和励志名言\n\n简单说，我就是你身边的全能技术助手，有什么技术问题或者想了解博客内容，尽管问我！😄', 'blog_assistant', NULL, 0, 0, 'success', NULL, '2025-12-31 08:22:59', '2025-12-31 08:22:59');
INSERT INTO `ai_chats` VALUES (22, 1, 'chat_1768397981255', 'user', '今天天气怎么样', 'blog_assistant', NULL, 0, 0, 'success', NULL, '2026-01-14 13:39:53', '2026-01-14 13:39:53');
INSERT INTO `ai_chats` VALUES (23, 1, 'chat_1768397981255', 'assistant', '我目前无法直接获取实时天气信息，不过我可以给你一些实用的建议：\n\n**获取天气的方式：**\n- 查看手机自带的天气应用\n- 访问天气网站如中国天气网、Weather.com\n- 问智能音箱或手机语音助手\n- 查看当地气象台发布的天气预报\n\n**天气相关的小贴士：**\n- 最近季节转换，早晚温差可能较大，建议随身带件薄外套\n- 如果是阴雨天，记得带伞出门\n- 关注空气质量指数，必要时佩戴口罩\n\n如果你告诉我具体城市，我可以基于一般气候知识给你一些季节性的穿衣建议！或者你需要我帮你搜索一些天气相关的技术文章吗？', 'blog_assistant', NULL, 0, 0, 'success', NULL, '2026-01-14 13:39:59', '2026-01-14 13:39:59');
INSERT INTO `ai_chats` VALUES (24, 1, 'session_1768398692964', 'user', '请帮我写一篇关于【agent】的教程，要求步骤清晰、易于理解、包含实例说明。', 'blog_assistant', NULL, 0, 0, 'success', NULL, '2026-01-14 13:51:32', '2026-01-14 13:51:32');
INSERT INTO `ai_chats` VALUES (25, 1, 'session_1768398692964', 'assistant', '# 智能代理（Agent）完全指南：从入门到实战\n\n## 什么是智能代理？\n\n智能代理（Agent）是一种能够感知环境、自主决策并执行行动的智能系统。在AI领域，Agent通常指能够理解用户意图、调用工具、完成任务的人工智能程序。\n\n## Agent的核心组成\n\n一个完整的Agent通常包含以下组件：\n\n1. **感知模块** - 接收和理解用户输入\n2. **决策引擎** - 分析需求并制定行动计划\n3. **工具集** - 可调用的各种功能模块\n4. **记忆系统** - 存储对话历史和上下文\n5. **执行器** - 实际执行操作并返回结果\n\n## 实战教程：构建一个简单的天气查询Agent\n\n### 步骤1：定义Agent的能力范围\n\n```python\nclass WeatherAgent:\n    def __init__(self):\n        self.tools = {\n            \'get_current_weather\': self.get_current_weather,\n            \'get_forecast\': self.get_forecast,\n            \'convert_temperature\': self.convert_temperature\n        }\n    \n    def understand_intent(self, user_input):\n        \"\"\"分析用户意图\"\"\"\n        if \'天气\' in user_input and \'现在\' in user_input:\n            return \'get_current_weather\'\n        elif \'预报\' in user_input:\n            return \'get_forecast\'\n        elif \'温度转换\' in user_input:\n            return \'convert_temperature\'\n        else:\n            return \'unknown\'\n```\n\n### 步骤2：实现具体工具函数\n\n```python\n    def get_current_weather(self, location):\n        \"\"\"获取当前天气（模拟实现）\"\"\"\n        # 实际应用中这里会调用天气API\n        weather_data = {\n            \'北京\': {\'温度\': \'25°C\', \'天气\': \'晴\', \'湿度\': \'45%\'},\n            \'上海\': {\'温度\': \'28°C\', \'天气\': \'多云\', \'湿度\': \'60%\'},\n            \'广州\': {\'温度\': \'30°C\', \'天气\': \'阵雨\', \'湿度\': \'75%\'}\n        }\n        return weather_data.get(location, \'未知地点\')\n\n    def convert_temperature(self, value, from_unit, to_unit):\n        \"\"\"温度单位转换\"\"\"\n        if from_unit == \'celsius\' and to_unit == \'fahrenheit\':\n            return (value * 9/5) + 32\n        elif from_unit == \'fahrenheit\' and to_unit == \'celsius\':\n            return (value - 32) * 5/9\n        return value\n```\n\n### 步骤3：构建对话循环\n\n```python\n    def run(self):\n        \"\"\"运行Agent的主循环\"\"\"\n        print(\"天气助手已启动！输入\'退出\'结束对话\")\n        \n        while True:\n            user_input = input(\"\\n您：\")\n            \n            if user_input == \'退出\':\n                print(\"再见！\")\n                break\n                \n            intent = self.understand_intent(user_input)\n            \n            if intent == \'unknown\':\n                print(\"抱歉，我不理解您的请求\")\n                continue\n                \n            # 提取关键信息（这里简化处理）\n            if \'北京\' in user_input:\n                location = \'北京\'\n            elif \'上海\' in user_input:\n                location = \'上海\'\n            elif \'广州\' in user_input:\n                location = \'广州\'\n            else:\n                location = \'北京\'  # 默认值\n                \n            # 执行对应的工具\n            result = self.tools[intent](location)\n            print(f\"助手：{result}\")\n```\n\n### 步骤4：测试Agent\n\n```python\n# 创建并运行Agent\nagent = WeatherAgent()\nagent.run()\n```\n\n## 高级Agent设计模式\n\n### 模式1：工具调用链\n\n```python\nclass AdvancedAgent:\n    def plan_actions(self, goal):\n        \"\"\"制定行动计划\"\"\"\n        steps = []\n        if \"旅行规划\" in goal:\n            steps = [\n                \'查询天气\',\n                \'查找航班\',\n                \'预订酒店\',\n                \'生成行程\'\n            ]\n        return steps\n    \n    def execute_plan(self, steps):\n        \"\"\"按计划执行\"\"\"\n        results = []\n        for step in steps:\n            result = self.call_tool(step)\n            results.append(result)\n        return results\n```\n\n### 模式2：记忆增强\n\n```python\nclass MemoryEnhancedAgent:\n    def __init__(self):\n        self.conversation_history = []\n        self.user_preferences = {}\n    \n    def remember_context(self, user_input, response):\n        \"\"\"记住对话上下文\"\"\"\n        self.conversation_history.append({\n            \'user\': user_input,\n            \'assistant\': response,\n            \'timestamp\': \'当前时间\'\n        })\n    \n    def get_relevant_context(self, current_input):\n        \"\"\"获取相关上下文\"\"\"\n        # 简单的关键词匹配，实际可以使用向量搜索\n        relevant = []\n        for item in self.conversation_history[-5:]:  # 最近5条\n            if any(word in current_input for word in item[\'user\'].split()):\n                relevant.append(item)\n        return relevant\n```\n\n## 实际应用示例：博客搜索Agent# AI Agent 开发完全指南：从入门到实战\n\n## 什么是 AI Agent？\n\nAI Agent（智能代理）是一种能够感知环境、自主决策并执行任务的智能系统。与传统的程序不同，Agent 具备自主性、反应性、目标导向性和学习能力。\n\n## 基础概念\n\n### Agent 的核心特性\n- **自主性**：无需人工干预即可运行\n- **反应性**：能够感知环境变化并作出响应  \n- **目标导向**：有明确的目标和任务\n- **学习能力**：能够从经验中改进性能\n\n## 实战教程：构建一个简单的天气查询 Agent\n\n### 步骤1：定义 Agent 的能力\n\n```javascript\n// weatherAgent.js\nclass WeatherAgent {\n  constructor() {\n    this.name = \"天气助手\";\n    this.capabilities = [\"查询天气\", \"提供穿衣建议\", \"预警提醒\"];\n  }\n  \n  // 感知环境（用户输入）\n  perceive(input) {\n    return {\n      location: this.extractLocation(input),\n      intent: this.analyzeIntent(input),\n      timestamp: new Date()\n    };\n  }\n  \n  // 决策逻辑\n  decide(perception) {\n    if (perception.intent === \"查询天气\") {\n      return \"fetchWeather\";\n    } else if (perception.intent === \"穿衣建议\") {\n      return \"provideAdvice\";\n    }\n    return \"askClarification\";\n  }\n  \n  // 执行动作\n  async act(action, perception) {\n    switch(action) {\n      case \"fetchWeather\":\n        return await this.fetchWeatherData(perception.location);\n      case \"provideAdvice\":\n        return this.generateClothingAdvice(perception.location);\n      default:\n        return \"请告诉我您想查询哪个城市的天气？\";\n    }\n  }\n}\n```\n\n### 步骤2：实现具体功能\n\n```javascript\n// 扩展 WeatherAgent 类\nclass WeatherAgent {\n  // ... 之前的代码 ...\n  \n  async fetchWeatherData(city) {\n    try {\n      // 模拟 API 调用\n      const weather = await this.mockWeatherAPI(city);\n      return `${city}的天气：${weather.temperature}°C，${weather.condition}`;\n    } catch (error) {\n      return `抱歉，无法获取${city}的天气信息`;\n    }\n  }\n  \n  generateClothingAdvice(city) {\n    const adviceMap = {\n      \"北京\": \"今天北京较冷，建议穿厚外套\",\n      \"上海\": \"上海天气温和，薄外套即可\",\n      \"广州\": \"广州温暖，短袖舒适\"\n    };\n    return adviceMap[city] || \"请提供具体城市名称\";\n  }\n  \n  extractLocation(input) {\n    const cities = [\"北京\", \"上海\", \"广州\", \"深圳\"];\n    return cities.find(city => input.includes(city)) || \"未知\";\n  }\n  \n  analyzeIntent(input) {\n    if (input.includes(\"天气\")) return \"查询天气\";\n    if (input.includes(\"穿什么\") || input.includes(\"穿衣\")) return \"穿衣建议\";\n    return \"未知\";\n  }\n}\n```\n\n### 步骤3：创建交互界面\n\n```html\n<!-- agent-interface.html -->\n<!DOCTYPE html>\n<html>\n<head>\n    <title>天气助手 Agent</title>\n    <style>\n        .chat-container { max-width: 600px; margin: 0 auto; }\n        .message { padding: 10px; margin: 5px; border-radius: 10px; }\n        .user { background: #e3f2fd; text-align: right; }\n        .agent { background: #f5f5f5; }\n    </style>\n</head>\n<body>\n    <div class=\"chat-container\">\n        <div id=\"chat-messages\"></div>\n        <input type=\"text\" id=\"user-input\" placeholder=\"输入您的问题...\">\n        <button onclick=\"handleUserInput()\">发送</button>\n    </div>\n\n    <script>\n        const agent = new WeatherAgent();\n        \n        function handleUserInput() {\n            const input = document.getElementById(\'user-input\').value;\n            const perception = agent.perceive(input);\n            const action = agent.decide(perception);\n            \n            agent.act(action, perception).then(response => {\n                displayMessage(input, \'user\');\n                displayMessage(response, \'agent\');\n            });\n            \n            document.getElementById(\'user-input\').value = \'\';\n        }\n        \n        function displayMessage(text, sender) {\n            const messagesDiv = document.getElementById(\'chat-messages\');\n            const messageDiv = document.createElement(\'div\');\n            messageDiv.className = `message ${sender}`;\n            messageDiv.textContent = text;\n            messagesDiv.appendChild(messageDiv);\n        }\n    </script>\n</body>\n</html>\n```\n\n## 高级功能：让 Agent 更智能\n\n### 1. 记忆能力\n```javascript\nclass EnhancedWeatherAgent extends WeatherAgent {\n  constructor() {\n    super();\n    this.memory = new Map(); // 存储对话历史\n    this.preferences = {};   // 用户偏好\n  }\n  \n  remember(userId, key, value) {\n    if (!this.memory.has(userId)) {\n      this.memory.set(userId, new Map());\n    }\n    this.memory.get(userId).set(key, value);\n  }\n  \n  recall(userId, key) {\n    return this.memory.get(userId)?.get(key);\n  }\n}\n```\n\n### 2. 学习能力\n```javascript\n// 基于用户反馈的学习\nclass LearningAgent extends EnhancedWeatherAgent {\n  learnFromFeedback(feedback, correctResponse) {\n    // 分析反馈，调整决策逻辑\n    if (feedback === \"不满意\") {\n      this.adjustDecisionWeights();\n    }\n  }\n  \n  adjustDecisionWeights() {\n    // 实现简单的强化学习逻辑\n    console.log(\"根据反馈调整决策权重...\");\n  }\n}\n```\n\n## 实际应用示例\n\n### 示例1：电商客服 Agent\n```javascript\nclass EcommerceAgent {\n  handleCustomerQuery(query) {\n    const intent = this.classifyIntent(query);\n    \n    switch(intent) {\n      case \"订单查询\":\n        return this.checkOrderStatus(query);\n      case \"产品推荐\":\n        return this.recommendProducts(query);\n      case \"售后服务\":\n        return this.handleAfterSales(query);\n      default:\n        return this.escalateToHuman(query);\n    }\n  }\n}\n```\n\n### 示例2：智能家居控制 Agent\n```javascript\nclass SmartHomeAgent {\n  controlDevice(command) {\n    const devices = this.parseDevices(command);\n    const actions = this.extractActions(command);\n    \n    devices.forEach(device => {\n      actions.forEach(action => {\n        this.executeDeviceCommand(device, action);\n      });\n    });\n  }\n}\n```\n\n## 最佳实践\n\n### 1. 错误处理\n```javascript\nclass RobustAgent {\n  async actSafely(action, perception) {\n    try {\n      return await this.act(action, perception);\n    } catch (error) {\n      console.error(\"Agent 执行错误:\", error);\n      return this.getFallbackResponse(perception);\n    }\n  }\n}\n```\n\n### 2. 性能优化\n```javascript\n// 使用缓存提高响应速度\nclass OptimizedAgent {\n  constructor() {\n    this.cache = new Map();\n    this.cacheTimeout = 300000; // 5分钟缓存\n  }\n  \n  async getCachedData(key, fetchFunction) {\n    const cached = this.cache.get(key);\n    if (cached && Date.now() - cached.timestamp < this.cacheTimeout) {\n      return cached.data;\n    }\n    \n    const freshData = await fetchFunction();\n    this.cache.set(key, { data: freshData, timestamp: Date.now() });\n    return freshData;\n  }\n}\n```\n\n## 总结\n\n通过本教程，你已经学会了：\n- Agent 的基本概念和架构\n- 如何构建一个功能完整的天气查询 Agent\n- 实现记忆和学习能力的高级技巧\n- 实际应用场景的最佳实践\n\nAgent 开发的关键在于**清晰的架构设计**和**稳健的错误处理**。随着 AI 技术的发展，Agent 将在更多领域发挥重要作用！\n\n**想了解更多？** 我还可以帮你构建更复杂的 Agent 系统，比如多 Agent 协作、自主决策引擎等。有什么具体需求尽管告诉我！', 'blog_assistant', NULL, 0, 0, 'success', NULL, '2026-01-14 13:53:14', '2026-01-14 13:53:14');

-- ----------------------------
-- Table structure for ai_chats_archive
-- ----------------------------
DROP TABLE IF EXISTS `ai_chats_archive`;
CREATE TABLE `ai_chats_archive`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `user_id` int NOT NULL COMMENT '用户ID',
  `session_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '会话ID',
  `message` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '用户消息',
  `response` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'AI回复',
  `type` enum('chat','blog_assistant','writing_assistant') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'chat' COMMENT '聊天类型',
  `context` json NULL COMMENT '上下文信息',
  `tokens` int NULL DEFAULT 0 COMMENT '消耗的token数量',
  `duration` int NULL DEFAULT 0 COMMENT '响应时间(毫秒)',
  `status` enum('success','failed','processing') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'success' COMMENT '状态',
  `error` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '错误信息',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_userId`(`user_id` ASC) USING BTREE,
  INDEX `idx_sessionId`(`session_id` ASC) USING BTREE,
  INDEX `idx_createdAt`(`created_at` ASC) USING BTREE,
  INDEX `idx_ai_chats_type_status`(`type` ASC, `status` ASC) USING BTREE,
  INDEX `idx_ai_chats_userId_createdAt`(`user_id` ASC, `created_at` ASC) USING BTREE,
  INDEX `idx_ai_chats_user_created`(`user_id` ASC, `created_at` DESC) USING BTREE COMMENT '用户聊天记录时间索引',
  INDEX `idx_ai_chats_session_created`(`session_id` ASC, `created_at` DESC) USING BTREE COMMENT '会话时间索引'
) ENGINE = InnoDB AUTO_INCREMENT = 5 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'AI聊天记录归档表（保存3个月以前的数据）' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of ai_chats_archive
-- ----------------------------
INSERT INTO `ai_chats_archive` VALUES (1, 1, 'session_001', '你好，请介绍一下这个博客系统', '你好！这是一个功能丰富的博客系统，支持文章管理、用户管理、评论系统等功能。系统还集成了AI助手，可以帮助用户进行内容创作、分析和优化。', 'chat', '{\"topic\": \"system_intro\", \"user_level\": \"admin\"}', 150, 1200, 'success', NULL, '2025-01-28 10:30:00', '2025-01-28 10:30:01');
INSERT INTO `ai_chats_archive` VALUES (2, 1, 'session_001', '如何优化文章SEO？', '优化文章SEO可以从以下几个方面入手：\n1. 关键词优化：在标题、内容中合理使用关键词\n2. 内容质量：提供有价值、原创的内容\n3. 结构优化：使用合适的标题层级、段落结构\n4. 图片优化：添加alt标签、压缩图片\n5. 内部链接：建立合理的内部链接结构\n6. 移动端优化：确保在移动设备上的良好体验', 'chat', '{\"topic\": \"seo_optimization\", \"user_level\": \"admin\"}', 280, 2500, 'success', NULL, '2025-01-28 10:35:00', '2025-01-28 10:35:02');
INSERT INTO `ai_chats_archive` VALUES (3, 1, 'session_002', '帮我生成一篇关于JavaScript的文章', '好的，我来为你生成一篇关于JavaScript的文章：\n\n# JavaScript：现代Web开发的核心语言\n\nJavaScript作为现代Web开发的核心语言，已经发展成为一个功能强大且灵活的工具。从简单的表单验证到复杂的单页应用，JavaScript无处不在。\n\n## 核心特性\n\nJavaScript具有以下核心特性：\n- 动态类型\n- 函数式编程支持\n- 面向对象编程\n- 异步编程\n\n## 现代JavaScript\n\nES6+引入了许多新特性，如箭头函数、解构赋值、模块系统等，使JavaScript更加现代化和易用。', 'blog_assistant', '{\"style\": \"technical\", \"topic\": \"javascript_article\", \"length\": \"medium\"}', 450, 3500, 'success', NULL, '2025-01-28 11:00:00', '2025-01-28 11:00:03');
INSERT INTO `ai_chats_archive` VALUES (4, 1, 'session_003', '分析一下我的博客数据', '根据你的博客数据分析，以下是主要发现：\n\n## 访问统计\n- 总访问量：1,250次\n- 独立访客：890人\n- 平均停留时间：3分45秒\n\n## 热门内容\n1. JavaScript相关文章（访问量：320次）\n2. 技术教程类文章（访问量：280次）\n3. 生活随笔类文章（访问量：180次）\n\n## 用户行为\n- 移动端访问占比：65%\n- 搜索引擎来源：40%\n- 直接访问：35%\n- 社交媒体：25%\n\n## 建议\n1. 增加JavaScript相关内容\n2. 优化移动端体验\n3. 加强SEO优化', 'chat', '{\"topic\": \"blog_analysis\", \"data_type\": \"statistics\"}', 320, 2800, 'success', NULL, '2025-01-28 14:20:00', '2025-01-28 14:20:02');

-- ----------------------------
-- Table structure for ai_quotas
-- ----------------------------
DROP TABLE IF EXISTS `ai_quotas`;
CREATE TABLE `ai_quotas`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `user_id` int NOT NULL COMMENT '用户ID',
  `daily_chat_limit` int NULL DEFAULT 100 COMMENT '每日聊天次数限制',
  `daily_chat_used` int NULL DEFAULT 0 COMMENT '每日聊天已使用次数',
  `daily_generate_limit` int NULL DEFAULT 50 COMMENT '每日内容生成次数限制',
  `daily_generate_used` int NULL DEFAULT 0 COMMENT '每日内容生成已使用次数',
  `monthly_token_limit` int NULL DEFAULT 100000 COMMENT '每月token使用限制',
  `monthly_token_used` int NULL DEFAULT 0 COMMENT '每月token已使用量',
  `last_reset_date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '上次重置日期',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_userId`(`user_id` ASC) USING BTREE,
  CONSTRAINT `fk_ai_quotas_userId` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 10 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'AI配额表' ROW_FORMAT = DYNAMIC;

