-- ----------------------------
-- Table structure for friend_links
-- ----------------------------
DROP TABLE IF EXISTS `friend_links`;
CREATE TABLE `friend_links`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '友链名称',
  `url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '友链地址',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '友链描述',
  `avatar` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '头像地址',
  `theme_color` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '主题色（用于前端展示）',
  `tags` json NULL COMMENT '标签数组',
  `status` enum('pending','approved','rejected','blocked') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending' COMMENT '审核状态',
  `is_featured` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否推荐展示',
  `order` int NOT NULL DEFAULT 0 COMMENT '排序值（越大越靠前）',
  `owner_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '站长昵称',
  `owner_email` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '站长邮箱（仅博主可见）',
  `apply_user_id` int NULL DEFAULT NULL COMMENT '申请用户ID（登录申请时记录）',
  `click_count` int NOT NULL DEFAULT 0 COMMENT '点击次数',
  `last_click_at` datetime NULL DEFAULT NULL COMMENT '最后点击时间',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_friend_status_featured_order_created`(`status` ASC, `is_featured` ASC, `order` ASC, `created_at` ASC) USING BTREE,
  INDEX `idx_friend_apply_user`(`apply_user_id` ASC) USING BTREE,
  CONSTRAINT `fk_friend_apply_user` FOREIGN KEY (`apply_user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 4 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci ROW_FORMAT = Dynamic;

