-- ----------------------------
-- Table structure for posts
-- ----------------------------
DROP TABLE IF EXISTS `posts`;
CREATE TABLE `posts`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'id',
  `title` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `content` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `summary` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL,
  `cover_image` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `status` int NULL DEFAULT 0,
  `audit_status` tinyint NOT NULL DEFAULT 0 COMMENT '审核状态（0-待审核，1-审核通过，2-审核驳回）',
  `view_count` int NULL DEFAULT 0,
  `like_count` int NULL DEFAULT 0,
  `type_id` bigint NOT NULL COMMENT '分类id',
  `user_id` int NOT NULL COMMENT '作者ID（外键关联users表）',
  `published_at` datetime NULL DEFAULT NULL COMMENT '发布时间',
  `last_read_at` datetime NULL DEFAULT NULL COMMENT '最后阅读时间',
  `created_at` datetime NOT NULL COMMENT '创建时间',
  `updated_at` datetime NOT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_userId`(`user_id` ASC) USING BTREE,
  INDEX `idx_status_publishedAt`(`status` ASC, `published_at` ASC) USING BTREE,
  INDEX `idx_categroupId`(`type_id` ASC) USING BTREE,
  INDEX `idx_audit_status`(`audit_status` ASC) USING BTREE,
  INDEX `idx_status_audit`(`status` ASC, `audit_status` ASC) USING BTREE,
  INDEX `idx_last_read_at`(`last_read_at` ASC) USING BTREE,
  INDEX `idx_posts_status_published`(`status` ASC, `published_at` DESC) USING BTREE COMMENT '文章状态发布时间索引',
  INDEX `idx_posts_user_status`(`user_id` ASC, `status` ASC, `published_at` DESC) USING BTREE COMMENT '用户文章状态索引',
  INDEX `idx_posts_view_count`(`view_count` DESC) USING BTREE,
  INDEX `idx_posts_like_count`(`like_count` DESC) USING BTREE,
  INDEX `idx_posts_created_at`(`created_at` DESC) USING BTREE,
  FULLTEXT INDEX `ft_posts_search`(`title`, `content`) WITH PARSER `ngram` COMMENT '文章全文搜索索引',
  CONSTRAINT `posts_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE = InnoDB AUTO_INCREMENT = 24 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci ROW_FORMAT = COMPRESSED;

-- ----------------------------
-- Records of posts
-- ----------------------------
INSERT INTO `posts` VALUES (4, '[Vite]使用PostCss实现响应式', '<h3>1、安装依赖</h3><p>首先，需要安装 <code>postcss</code> 和 <code>postcss-px-to-viewport</code> 这两个依赖。你可以使用 npm 或 yarn 来安装它们：</p><pre><code class=\"language-javascript\">npm install postcss postcss-px-to-viewport --save-dev</code></pre><h3>2、配置PostCss</h3><p>在 Vite 工程中，PostCSS 的配置通常是在 <code>vite.config.js</code> 或 <code>vite.config.ts</code> 文件中进行的。你需要在这个文件中添加 PostCSS 的配置，并引入 <code>postcss-px-to-viewport</code> 插件。</p><p>以下是一个示例配置：</p><pre><code class=\"language-javascript\">//vite.config.js\nimport { defineConfig } from \'vite\';\n//引入postcss-px-to-viewport\nimport postcss from \'postcss\';\nimport pxToViewport from \'postcss-px-to-viewport\';\n\nexport default defineConfig({\n  css: {\n    postcss: {\n      plugins: [\n        pxToViewport({\n          unitToConvert: \'px\', // 需要转换的单位，默认为\'px\'\n          viewportWidth: 375,  // 基准视口宽度（对应设计稿的宽度）\n          viewportHeight: 667, // 视口高度（可选）\n          unitPrecision: 5,    // px转换为vw的小数位数（很多情况下用5）\n          propList: [\'*\'],     // 指定需要转换的属性，\'*\'表示全部转换，\'font-size\'表示只转换font-size属性\n          viewportUnit: \'vmin\',  // 指定需要转换成的视口单位，默认vw\n          fontViewportUnit: \'vmin\', // 字体使用的视口单位，默认vw\n          selectorBlackList: [], // 指定不转换为视口单位的类名，用逗号隔开\n          minPixelValue: 1,    // 小于或等于1px不转换为视口单位，默认1\n          mediaQuery: false,   // 允许在媒体查询中转换px\n          replace: true,       // 是否直接替换而不是添加后缀\n          exclude: /node_modules/ // 设置忽略文件，用正则表达式匹配路径\n        }),\n      ]\n    }\n  },\n});\n</code></pre><p></p>', '本文介绍了在Vite工程中使用PostCSS及插件postcss-px-to-viewport进行px单位到视口单位的转换。首先通过npm或yarn安装相关依赖，然后在vite.config.js或vite.config.ts中配置PostCSS并引入该插件。配置包括转换单位、基准视口宽度、小数精度、转换属性、视口单位等选项，支持排除特定文件或类名，以及是否在媒体查询中转换。该配置有助于提高响应式布局的效率。', NULL, 1, 1, 204, 1, 1, 1, '2024-10-21 07:18:06', '2026-01-07 00:58:05', '2025-10-21 07:18:06', '2026-01-07 01:23:17');
INSERT INTO `posts` VALUES (5, '图片热区点击、悬停、离开功能', '<img class=\"editor-image\" src=\"/uploads/general/2025/10/ef910d4cd50de640df9a65ee9215e0f0.png\" width=\"841\" height=\"402\" data-align=\"center\" style=\"width: 841px; height: 402px;\"><h3>如图，需要点击图片中的区域去弹出信息</h3><h3>封装一个公共的组件，将需要用到的区域去遍历到组件里并绑定事件</h3><pre><code class=\"language-javascript\">&lt;template&gt;\n  &lt;div class=\"image-mapper\" ref=\"mapperRef\"&gt;\n    &lt;!-- 底图 --&gt;\n    &lt;img\n      :src=\"props.src\"\n      @load=\"handleImageLoad\"\n      :style=\"imageStyle\"\n      class=\"base-image\"\n    /&gt;\n\n    &lt;!-- 区域层 --&gt;\n    &lt;div class=\"areas-container\" :style=\"containerStyle\"&gt;\n      &lt;template v-for=\"(area, index) in computedAreas\" :key=\"index\"&gt;\n        &lt;!-- 矩形区域 --&gt;\n        &lt;div\n          v-if=\"area.shape === \'rect\'\"\n          class=\"area rectangle\"\n          :style=\"area.style\"\n          @click=\"handleAreaClick(area)\"\n          @mouseover=\"handleAreaHover(area)\"\n          @mouseleave=\"handleAreaLeave(area)\"\n        &gt;\n          &lt;div v-if=\"showTooltip &amp;&amp; hoveredArea === area\" class=\"tooltip\"&gt;\n            {{ area.title }}\n          &lt;/div&gt;\n        &lt;/div&gt;\n\n        &lt;!-- 圆形区域 --&gt;\n        &lt;div\n          v-else-if=\"area.shape === \'circle\'\"\n          class=\"area circle\"\n          :style=\"area.style\"\n          @click=\"handleAreaClick(area)\"\n          @mouseover=\"handleAreaHover(area)\"\n          @mouseleave=\"handleAreaLeave(area)\"\n        &gt;\n          &lt;div v-if=\"showTooltip &amp;&amp; hoveredArea === area\" class=\"tooltip\"&gt;\n            {{ area.title }}\n          &lt;/div&gt;\n        &lt;/div&gt;\n\n        &lt;!-- 多边形区域 --&gt;\n        &lt;div\n          v-else-if=\"area.shape === \'poly\'\"\n          class=\"area polygon\"\n          :style=\"area.style\"\n          @click=\"handleAreaClick(area)\"\n          @mouseover=\"handleAreaHover(area)\"\n          @mouseleave=\"handleAreaLeave(area)\"\n        &gt;\n          &lt;div v-if=\"showTooltip &amp;&amp; hoveredArea === area\" class=\"tooltip\"&gt;\n            {{ area.title }}\n          &lt;/div&gt;\n        &lt;/div&gt;\n      &lt;/template&gt;\n    &lt;/div&gt;\n  &lt;/div&gt;\n&lt;/template&gt;\n\n&lt;script setup&gt;\nimport { ref, computed, onMounted, onUnmounted } from \"vue\";\nimport { useElementSize } from \"@vueuse/core\";\n\nconst props = defineProps({\n  src: {\n    type: String,\n    required: true,\n  },\n  areas: {\n    type: Array,\n    default: () =&gt; [],\n  },\n  responsive: {\n    type: Boolean,\n    default: true,\n  },\n  showTooltip: {\n    type: Boolean,\n    default: true,\n  },\n});\n\nconst emit = defineEmits([\"click\", \"mouseover\", \"mouseleave\"]);\n\nconst mapperRef = ref(null);\nconst { width: containerWidth } = useElementSize(mapperRef);\nconst naturalWidth = ref(0);\nconst naturalHeight = ref(0);\nconst hoveredArea = ref(null);\n\n// 计算缩放比例\nconst scale = computed(() =&gt; {\n  if (!props.responsive || !naturalWidth.value) return 1;\n  return containerWidth.value / naturalWidth.value;\n});\n\n// 图片样式\nconst imageStyle = computed(() =&gt; ({\n  width: props.responsive ? \"100%\" : `${naturalWidth.value}px`,\n  height: props.responsive ? \"auto\" : `${naturalHeight.value}px`,\n}));\n\n// 容器样式\nconst containerStyle = computed(() =&gt; ({\n  position: \"absolute\",\n  top: 0,\n  left: 0,\n  width: props.responsive ? \"100%\" : `${naturalWidth.value}px`,\n  height: props.responsive ? \"auto\" : `${naturalHeight.value}px`,\n}));\n\n// 处理区域样式计算\nconst computedAreas = computed(() =&gt; {\n  return props.areas.map((area) =&gt; {\n    const style = calculateAreaStyle(area);\n    return {\n      ...area,\n      style,\n    };\n  });\n});\n\n// 计算区域样式\nconst calculateAreaStyle = (area) =&gt; {\n  const baseStyle = {\n    position: \"absolute\",\n    cursor: \"pointer\",\n  };\n\n  switch (area.shape) {\n    case \"rect\":\n      const [x, y, width, height] = area.coords;\n      return {\n        ...baseStyle,\n        left: `${x * scale.value}px`,\n        top: `${y * scale.value}px`,\n        width: `${width * scale.value}px`,\n        height: `${height * scale.value}px`,\n      };\n\n    case \"circle\":\n      const [cx, cy, r] = area.coords;\n      return {\n        ...baseStyle,\n        left: `${(cx - r) * scale.value}px`,\n        top: `${(cy - r) * scale.value}px`,\n        width: `${r * 2 * scale.value}px`,\n        height: `${r * 2 * scale.value}px`,\n        borderRadius: \"50%\",\n      };\n\n    case \"poly\":\n      const points = area.coords\n        .map((coord, index) =&gt;\n          index % 2 === 0\n            ? `${coord * scale.value}px`\n            : `${coord * scale.value}px`\n        )\n        .join(\",\");\n      return {\n        ...baseStyle,\n        clipPath: `polygon(${points})`,\n      };\n\n    default:\n      return baseStyle;\n  }\n};\n\n// 图片加载完成处理\nconst handleImageLoad = (e) =&gt; {\n  naturalWidth.value = e.target.naturalWidth;\n  naturalHeight.value = e.target.naturalHeight;\n};\n\n// 区域点击处理\nconst handleAreaClick = (area) =&gt; {\n  emit(\"click\", area);\n};\n\n// 区域悬停处理\nconst handleAreaHover = (area) =&gt; {\n  hoveredArea.value = area;\n  emit(\"mouseover\", area);\n};\n\n// 区域离开处理\nconst handleAreaLeave = (area) =&gt; {\n  hoveredArea.value = null;\n  emit(\"mouseleave\", area);\n};\n\n// 监听窗口大小变化\nconst handleResize = () =&gt; {\n  // 触发重新计算\n};\n\nonMounted(() =&gt; {\n  if (props.responsive) {\n    window.addEventListener(\"resize\", handleResize);\n  }\n});\n\nonUnmounted(() =&gt; {\n  if (props.responsive) {\n    window.removeEventListener(\"resize\", handleResize);\n  }\n});\n&lt;/script&gt;\n\n&lt;style scoped&gt;\n.image-mapper {\n  position: relative;\n  display: inline-block;\n  max-width: 100%;\n}\n\n.base-image {\n  display: block;\n  max-width: 100%;\n  height: auto;\n}\n\n.areas-container {\n  pointer-events: none;\n}\n\n.area {\n  pointer-events: auto;\n  transition: background-color 0.3s;\n  background-color: rgba(255, 255, 255, 0);\n}\n\n.area:hover {\n  background-color: rgba(255, 255, 255, 0.2);\n}\n\n.tooltip {\n  position: absolute;\n  background: rgba(0, 0, 0, 0.8);\n  color: white;\n  padding: 4px 8px;\n  border-radius: 4px;\n  font-size: 12px;\n  white-space: nowrap;\n  top: -30px;\n  left: 50%;\n  transform: translateX(-50%);\n  z-index: 1000;\n}\n&lt;/style&gt;</code></pre><h3>使用示例</h3><pre><code class=\"language-javascript\">&lt;template&gt;\n  &lt;div&gt;\n    &lt;ImageMapper\n      :src=\"getAssetsURL(imageUrl)\"\n      :areas=\"areas\"\n      @click=\"handleAreaClick\"\n      @mouseover=\"handleAreaHover\"\n      @mouseleave=\"handleAreaLeave\"\n    /&gt;\n  &lt;/div&gt;\n&lt;/template&gt;\n\n&lt;script setup&gt;\nimport ImageMapper from \"../utils/ImageMapper.vue\";\nimport { getAssetsURL } from \"@/utils/load_assets\";\n\nconst imageUrl = \"other/about/pc_aboutus_skf.png\";\n\nconst areas = [\n  {\n    id: 1,\n    shape: \"rect\",\n    coords: [286, 40, 648, 192], // [x, y, width, height]\n    title: \"矩形区域123\",\n  },\n  // {\n  //   id: 2,\n  //   shape: \"circle\",\n  //   coords: [200, 200, 50], // [centerX, centerY, radius]\n  //   title: \"圆形区域\",\n  // },\n  // {\n  //   id: 3,\n  //   shape: \"poly\",\n  //   coords: [300, 100, 400, 100, 350, 200], // [x1, y1, x2, y2, x3, y3, ...]\n  //   title: \"多边形区域\",\n  // },\n];\n\nconst handleAreaClick = (area) =&gt; {\n  alert(`点击了区域: ${area.title}`);\n};\n\nconst handleAreaHover = (area) =&gt; {\n  console.log(\"悬停区域:\", area);\n};\n\nconst handleAreaLeave = (area) =&gt; {\n  console.log(\"离开区域:\", area);\n};\n&lt;/script&gt;\n\n&lt;style scoped lang=\"scss\"&gt;\n/**\n* @description: *** 页\n* @author: duyong\n* @Date:\n*/\n@use \"@/assets/css/element-plus.scss\";\n&lt;/style&gt;</code></pre><h3>tips:如果图片是n倍导出，对应x,y,width,height也要*2,因为是基于图片去定位的</h3><p></p>', NULL, NULL, 1, 1, 628, 0, 1, 1, '2023-10-21 07:40:13', '2026-01-17 09:02:54', '2025-10-21 07:40:13', '2026-01-17 09:02:54');
INSERT INTO `posts` VALUES (6, '深入理解\"高效视频流释放，提升用户体验\"', '<h2>视频流管理</h2><h3>问题背景</h3><blockquote><p>在连续返回和进入界面获取视频流时，可能会遇到设备列表不完整的问题。为确保每次都能获取到所有设备，退出界面时应释放视频流资源。</p></blockquote><h3>视频流释放的重要性</h3><ul><li><p>避免设备占用导致的选择错误（如摄像头微焦镜头）</p></li><li><p>确保下次进入时能重新枚举所有可用设备</p></li></ul><h3>视频流管理的实现</h3><ol><li><p>初始化视频组件</p></li></ol><pre><code class=\"language-javascript\">&lt;video\n  v-show=\"videoStatus\"\n  id=\"video\"\n  object-fit=\"cover\"\n  :enable-progress-gesture=\"false\"\n  :show-center-play-btn=\"false\"\n  autoplay\n  muted\n  :controls=\"false\"\n  :playsinline=\"true\"\n  webkit-playsinline=\"true\"\n  x5-video-player-type=\"h5\"\n  x5-video-player-fullscreen=\"true\"\n  x5-video-orientation=\"portraint\"\n  :\n&gt;\n&lt;/video&gt;</code></pre><ol start=\"2\"><li><p>组件挂载与销毁</p></li></ol><ul><li><p>组件挂载时开始获取设备并初始化视频流</p></li><li><p>组件销毁时释放视频流和资源</p></li></ul><h3>获取摄像头设备</h3><pre><code class=\"language-javascript\">const getDevices = async () =&gt; {\n  // 省略部分代码...\n  // 停止现有的视频流（如果有的话）\n  // 获取设备列表并返回\n};\n</code></pre><h3>视频流处理逻辑</h3><blockquote><p>以下代码块展示了如何处理视频流，包括初始化、播放和停止等操作。</p></blockquote><pre><code class=\"language-javascript\">const startFun = async () =&gt; {\n  // 省略部分代码...\n  // 获取设备、设置约束、获取用户媒体流等\n  // 在获取新流之前确保旧流已停止\n  // 初始化视频元素并播放视频流\n  // 更新视频尺寸和状态\n};\n</code></pre><h3>清理摄像头资源</h3><pre><code class=\"language-javascript\">const clearCamera = () =&gt; {\n  // 更新视频状态\n  videoStatus.value = false;\n\n  // 停止视频流并清除相关资源\n  if (videoStream.value) {\n    videoStream.value.getTracks().forEach(track =&gt; track.stop());\n    videoStream.value = null;\n  }\n\n  // 清除视频元素\n  if (video.value) {\n    video.value.srcObject = null;\n    video.value.load(); // 重置视频元素\n  }\n};\n</code></pre><p>通过以上步骤，可以确保视频流管理的逻辑清晰、资源得到有效释放，进而提升用户体验。</p>', '文章阐述了视频流管理的重要性，并提出了一套实现方法。在视频组件初始化、挂载与销毁过程中，重点关注视频流的获取、处理和释放。为避免设备占用错误，确保设备列表完整，需在组件销毁时清理摄像头资源，停止视频流并重置视频元素。这些步骤有助于提升用户体验，确保视频流逻辑清晰、资源有效释放。', NULL, 1, 1, 115, 0, 1, 1, '2025-10-29 01:46:07', '2025-12-16 09:42:26', '2025-10-29 01:46:07', '2025-12-16 09:42:26');
INSERT INTO `posts` VALUES (7, '在React中封装socket.io的实践指南', '<p></p><p>在构建实时通信功能的Web应用时，<a target=\"_blank\" rel=\"noopener noreferrer\" href=\"http://socket.io\">socket.io</a>已成为开发者的首选库之一。React，作为一个用于构建用户界面的JavaScript库，与socket.io的结合可以为用户提供流畅的实时互动体验。以下是如何在React应用中封装并使用socket.io的深度扩展内容。</p><h3>核心概念与背景知识</h3><p>socket.io在客户端和服务器之间提供了一个基于事件的实时双向通信通道。以下是几个关键概念：</p><ul><li><p><strong>事件驱动：</strong>socket.io基于发布/订阅模式，允许任何一端发送或接收自定义事件。</p></li><li><p><strong>实时性：</strong>socket.io使用了WebSocket协议，当条件不允许时，会优雅地降级到长轮询等技术。</p></li><li><p><strong>跨平台：</strong>socket.io支持多种浏览器和移动平台，易于在React Native等环境中使用。</p></li></ul><h3>封装socket.io的步骤</h3><ol><li><p></p></li></ol><h4>安装socket.io-client</h4><p>在React项目的根目录下，使用npm或yarn安装<code>socket.io-client</code>包。</p><pre><code class=\"language-bash\">npm install socket.io-client</code></pre><ul><li><p></p></li></ul><h4>创建Socket组件</h4><p>在React组件中封装socket.io的连接和事件处理逻辑。</p><pre><code class=\"language-typescript\">\nclass SocketComponent extends \nReact.Component {\n  componentDidMount() {\n    this.socket = io(\'http://localhost:3001\');\n    // 绑定事件处理器\n\n    this.socket.on(\'message\', (data) =&gt; {\n      this.props.onMessage(data);\n    });\n  }\n  // 发送事件\n  sendMessage = (message) =&gt; {\n    this.socket.emit(\'message\', message);\n  }\n  render() {\n    return (\n      &lt;div&gt;\n        {this.props.children}\n      &lt;/div&gt;\n    );\n  }\n}\n    </code></pre><ul><li><p></p></li></ul><h4>在React组件中使用Socket组件</h4><p>在其他组件中，我们可以如下使用Socket组件来发送和接收消息。</p><pre><code class=\"language-typescript\">\nclass Chat extends React.Component {\n  state = {\n    messages: []\n  };\n  handleMessage = (message) =&gt; {\n    this.setState((prevState) =&gt; ({\n      messages: [...prevState.messages, message]\n    }));\n  };\n  render() {\n    return (\n      &lt;SocketComponent onMessage={this.handleMessage}&gt;\n        &lt;ChatInterface messages={this.state.messages} sendMessage={this.sendMessage}/&gt;\n      &lt;/SocketComponent&gt;\n    );\n  }\n}\n    </code></pre><h3>案例分析与延伸思考</h3><p>以下是一个具体的案例，展示如何在一个简单的聊天应用中实现React和socket.io的结合。</p><ul><li><p></p></li></ul><h4>案例：实时聊天室</h4><p>在聊天室中，当用户发送消息时，其他所有用户应立即看到该消息。</p><ul><li><p>使用socket.io建立服务器与客户端之间的实时连接。</p></li><li><p>在客户端，创建React组件来展示消息列表，并允许用户发送新消息。</p></li><li><p>当用户发送消息时，通过socket.io触发服务器的\'message\'事件。</p></li><li><p>服务器接收到消息后，广播给所有连接的客户端。</p></li></ul><ul><li><p></p></li></ul><h4>延伸思考</h4><p>在更复杂的实时应用中，我们还需考虑以下问题：</p><ul><li><p><em>连接管理：</em>如何优雅地处理用户断开重连、网络不稳定等情况？</p></li><li><p><em>性能优化：</em>如何减少不必要的事件发送和接收，避免性能瓶颈？</p></li><li><p><em>安全性：</em>如何确保通过socket.io传输的数据是加密和安全的？</p></li></ul><p>通过上述内容，我们可以看到在React中封装并使用socket.io不仅能够提升应用的实时交互能力，而且通过合理的组件封装和事件管理</p>', 'React封装使用socket.io', NULL, 1, 1, 44, 0, 1, 1, '2025-10-30 16:00:50', '2025-11-18 07:15:40', '2025-10-30 16:00:50', '2025-11-18 07:15:40');
INSERT INTO `posts` VALUES (8, 'Canvas打造高效蒙版绘制工具', '<h2>ComfyUI 与 Canvas 应用概述</h2><h3>1.1 ComfyUI 的功能与局限</h3><p>ComfyUI 允许用户将工作流导出为 API，便于外部网站调用。然而，在图像处理方面，它需要手动通过软件绘制蒙版，这一过程相对繁琐。为提升效率，我们考虑利用 HTML5 的 <code>canvas</code> 元素来实现一个蒙版绘制工具。</p><h3>1.2 蒙版绘制工具的优势</h3><ul><li><p>简化流程：在填写表单的同时，可以快速绘制蒙版。</p></li><li><p>提高效率：减少在不同软件间切换的时间，提升工作流。</p></li></ul><h2>2. Canvas 的应用</h2><h3>2.1 Canvas 简介</h3><blockquote><p>Canvas 是 HTML5 引入的一个元素，用于在网页上绘制图形和图像。它支持通过 JavaScript 进行动态渲染，非常适合开发交互式图像处理工具。</p></blockquote><h3>2.2 Canvas 实现蒙版绘制工具的原理</h3><ol><li><p>利用 Canvas API 创建一个画布。</p></li><li><p>通过用户交互（如鼠标或触摸事件）在画布上绘制图形。</p></li><li><p>将绘制的图形转换为蒙版，用于图像处理。</p></li></ol><h3>2.3 Canvas 的兼容性与拓展性</h3><p>Canvas 元素在现代浏览器上得到了广泛支持，可以用于实现各种复杂的图像处理功能。此外，其与 JavaScript 的良好结合，为开发更多交互式应用提供了可能。</p><h2>3. 示例</h2><h3>3.1 Vue组件</h3><pre><code class=\"language-javascript\">&lt;template&gt;\n  &lt;div class=\"image-mask-drawer\"&gt;\n    &lt;!-- 工具栏 --&gt;\n    &lt;div\n      class=\"toolbar flex items-center gap-3 mb-4 p-3 bg-gray-50 rounded-lg flex-wrap\"\n    &gt;\n      &lt;!-- 画笔形状 --&gt;\n      &lt;div class=\"flex items-center gap-2\"&gt;\n        &lt;label class=\"text-sm text-gray-700\"&gt;画笔形状:&lt;/label&gt;\n        &lt;div class=\"flex gap-1 bg-white rounded-md p-1 border border-gray-200\"&gt;\n          &lt;button\n            class=\"px-3 py-1 text-xs rounded transition-colors\"\n            :class=\"\n              brushShape === \'circle\'\n                ? \'bg-blue-600 text-white\'\n                : \'text-gray-600 hover:bg-gray-100\'\n            \"\n            @click=\"brushShape = \'circle\'\"\n          &gt;\n            ⚫ 圆形\n          &lt;/button&gt;\n          &lt;button\n            class=\"px-3 py-1 text-xs rounded transition-colors\"\n            :class=\"\n              brushShape === \'rect\'\n                ? \'bg-blue-600 text-white\'\n                : \'text-gray-600 hover:bg-gray-100\'\n            \"\n            @click=\"brushShape = \'rect\'\"\n          &gt;\n            ⬛ 矩形\n          &lt;/button&gt;\n        &lt;/div&gt;\n      &lt;/div&gt;\n\n      &lt;div class=\"h-6 w-px bg-gray-300\"&gt;&lt;/div&gt;\n\n      &lt;!-- 画笔大小 --&gt;\n      &lt;div class=\"flex items-center gap-2\"&gt;\n        &lt;label class=\"text-sm text-gray-700\"&gt;画笔大小:&lt;/label&gt;\n        &lt;input\n          v-model.number=\"brushSize\"\n          type=\"range\"\n          min=\"5\"\n          max=\"80\"\n          class=\"w-32\"\n        /&gt;\n        &lt;span class=\"text-sm text-gray-600\"&gt;{{ brushSize }}px&lt;/span&gt;\n      &lt;/div&gt;\n\n      &lt;div class=\"h-6 w-px bg-gray-300\"&gt;&lt;/div&gt;\n\n      &lt;button\n        class=\"px-3 py-1.5 text-sm bg-blue-600 text-white rounded hover:bg-blue-700 transition-colors\"\n        @click=\"clearMask\"\n      &gt;\n        清除遮罩\n      &lt;/button&gt;\n\n      &lt;button\n        class=\"px-3 py-1.5 text-sm bg-green-600 text-white rounded hover:bg-green-700 transition-colors\"\n        @click=\"confirmMask\"\n      &gt;\n        确认遮罩\n      &lt;/button&gt;\n\n      &lt;button\n        class=\"px-3 py-1.5 text-sm bg-gray-600 text-white rounded hover:bg-gray-700 transition-colors\"\n        @click=\"cancelEdit\"\n      &gt;\n        取消\n      &lt;/button&gt;\n\n      &lt;div class=\"ml-auto text-xs text-gray-500\"&gt;\n        💡 在图片上涂抹需要AI生成替换的区域\n      &lt;/div&gt;\n    &lt;/div&gt;\n\n    &lt;!-- Canvas 容器 --&gt;\n    &lt;div\n      class=\"canvas-container relative border-2 border-gray-300 rounded-lg overflow-hidden bg-gray-100\"\n    &gt;\n      &lt;canvas\n        ref=\"canvasRef\"\n        class=\"cursor-none\"\n        @mousedown=\"startDrawing\"\n        @mousemove=\"handleMouseMove\"\n        @mouseup=\"stopDrawing\"\n        @mouseleave=\"handleMouseLeave\"\n        @touchstart.prevent=\"handleTouchStart\"\n        @touchmove.prevent=\"handleTouchMove\"\n        @touchend.prevent=\"stopDrawing\"\n      &gt;&lt;/canvas&gt;\n\n      &lt;!-- 自定义光标预览 --&gt;\n      &lt;div\n        v-if=\"showCursor\"\n        class=\"brush-cursor pointer-events-none absolute border-2 border-blue-500 opacity-60\"\n        :class=\"brushShape === \'circle\' ? \'rounded-full\' : \'rounded-sm\'\"\n        :style=\"{\n          left: cursorPos.x + \'px\',\n          top: cursorPos.y + \'px\',\n          width: brushSize + \'px\',\n          height: brushSize + \'px\',\n          transform: \'translate(-50%, -50%)\',\n          backgroundColor: \'rgba(0, 0, 0, 0.2)\',\n        }\"\n      &gt;&lt;/div&gt;\n    &lt;/div&gt;\n\n    &lt;!-- 提示信息 --&gt;\n    &lt;div class=\"mt-3 text-xs text-gray-500\"&gt;\n      &lt;p&gt;• 用鼠标或手指在图片上涂抹，标记需要AI生成替换的区域&lt;/p&gt;\n      &lt;p&gt;• 涂抹的区域（黑色半透明）将被AI生成的新内容替换&lt;/p&gt;\n      &lt;p&gt;• 未涂抹的区域将保持原图不变&lt;/p&gt;\n    &lt;/div&gt;\n  &lt;/div&gt;\n&lt;/template&gt;\n\n&lt;script setup&gt;\nimport { ref, onMounted, watch } from \"vue\";\nimport { getProxiedImageUrl } from \"@/utils/image\";\n\nconst props = defineProps({\n  imageUrl: {\n    type: String,\n    required: true,\n  },\n  maxWidth: {\n    type: Number,\n    default: 800,\n  },\n  maxHeight: {\n    type: Number,\n    default: 600,\n  },\n});\n\nconst emit = defineEmits([\"confirm\", \"cancel\"]);\n\nconst canvasRef = ref(null);\nconst brushSize = ref(20);\nconst brushShape = ref(\"circle\"); // \'circle\' | \'rect\'\nconst isDrawing = ref(false);\nconst showCursor = ref(false);\nconst cursorPos = ref({ x: 0, y: 0 });\n\nlet ctx = null;\nlet image = null;\nlet maskCanvas = null;\nlet maskCtx = null;\nlet lastX = null;\nlet lastY = null;\n\n// 性能优化：使用 requestAnimationFrame\nlet rafId = null;\nlet pendingDraws = [];\n\nonMounted(() =&gt; {\n  initCanvas();\n});\n\nwatch(\n  () =&gt; props.imageUrl,\n  () =&gt; {\n    initCanvas();\n  }\n);\n\nconst initCanvas = async () =&gt; {\n  if (!props.imageUrl || !canvasRef.value) return;\n\n  const canvas = canvasRef.value;\n  ctx = canvas.getContext(\"2d\");\n\n  // 加载图片\n  image = new Image();\n  image.crossOrigin = \"anonymous\";\n\n  // 处理图片URL：如果是外部URL，通过后端代理\n  const imageUrl = getProxiedImageUrl(props.imageUrl, { log: true });\n\n  image.onload = () =&gt; {\n    // 计算缩放后的尺寸，保持比例\n    let width = image.width;\n    let height = image.height;\n\n    const widthRatio = props.maxWidth / width;\n    const heightRatio = props.maxHeight / height;\n    const ratio = Math.min(widthRatio, heightRatio);\n\n    width = Math.floor(width * ratio);\n    height = Math.floor(height * ratio);\n\n    // 设置canvas尺寸\n    canvas.width = width;\n    canvas.height = height;\n\n    // 创建遮罩层canvas\n    maskCanvas = document.createElement(\"canvas\");\n    maskCanvas.width = width;\n    maskCanvas.height = height;\n    maskCtx = maskCanvas.getContext(\"2d\");\n\n    // 绘制初始图片\n    redraw();\n  };\n\n  image.onerror = () =&gt; {\n    console.error(\"图片加载失败:\", props.imageUrl);\n  };\n\n  image.src = imageUrl;\n};\n\nconst redraw = () =&gt; {\n  if (!ctx || !image) return;\n\n  // 清空画布\n  ctx.clearRect(0, 0, canvasRef.value.width, canvasRef.value.height);\n\n  // 绘制原图\n  ctx.drawImage(image, 0, 0, canvasRef.value.width, canvasRef.value.height);\n\n  // 绘制遮罩层（黑色，不透明度0.8）\n  if (maskCanvas) {\n    ctx.globalAlpha = 0.8;\n    ctx.drawImage(maskCanvas, 0, 0);\n    ctx.globalAlpha = 1.0;\n  }\n};\n\n// 优化的重绘函数（使用 RAF）\nconst scheduleRedraw = () =&gt; {\n  if (rafId) return;\n\n  rafId = requestAnimationFrame(() =&gt; {\n    redraw();\n    rafId = null;\n  });\n};\n\nconst getMousePos = (e) =&gt; {\n  const rect = canvasRef.value.getBoundingClientRect();\n  const scaleX = canvasRef.value.width / rect.width;\n  const scaleY = canvasRef.value.height / rect.height;\n\n  return {\n    x: (e.clientX - rect.left) * scaleX,\n    y: (e.clientY - rect.top) * scaleY,\n  };\n};\n\nconst getTouchPos = (e) =&gt; {\n  const rect = canvasRef.value.getBoundingClientRect();\n  const touch = e.touches[0];\n  const scaleX = canvasRef.value.width / rect.width;\n  const scaleY = canvasRef.value.height / rect.height;\n\n  return {\n    x: (touch.clientX - rect.left) * scaleX,\n    y: (touch.clientY - rect.top) * scaleY,\n  };\n};\n\nconst startDrawing = (e) =&gt; {\n  isDrawing.value = true;\n  const pos = getMousePos(e);\n  lastX = pos.x;\n  lastY = pos.y;\n  drawBrush(pos.x, pos.y);\n};\n\nconst handleMouseMove = (e) =&gt; {\n  // 更新光标位置\n  const rect = canvasRef.value.getBoundingClientRect();\n  cursorPos.value = {\n    x: e.clientX - rect.left,\n    y: e.clientY - rect.top,\n  };\n  showCursor.value = true;\n\n  // 如果正在绘制，执行绘制操作\n  if (isDrawing.value) {\n    const pos = getMousePos(e);\n    interpolateDraw(lastX, lastY, pos.x, pos.y);\n    lastX = pos.x;\n    lastY = pos.y;\n  }\n};\n\nconst handleMouseLeave = () =&gt; {\n  showCursor.value = false;\n  stopDrawing();\n};\n\nconst stopDrawing = () =&gt; {\n  isDrawing.value = false;\n  lastX = null;\n  lastY = null;\n\n  // 最后绘制一次确保所有内容都显示\n  redraw();\n};\n\nconst handleTouchStart = (e) =&gt; {\n  isDrawing.value = true;\n  const pos = getTouchPos(e);\n  lastX = pos.x;\n  lastY = pos.y;\n  drawBrush(pos.x, pos.y);\n};\n\nconst handleTouchMove = (e) =&gt; {\n  if (!isDrawing.value) return;\n  const pos = getTouchPos(e);\n\n  // 插值绘制\n  interpolateDraw(lastX, lastY, pos.x, pos.y);\n\n  lastX = pos.x;\n  lastY = pos.y;\n};\n\n// 插值绘制，填补快速移动时的空隙\nconst interpolateDraw = (x0, y0, x1, y1) =&gt; {\n  const dist = Math.sqrt((x1 - x0) ** 2 + (y1 - y0) ** 2);\n  const steps = Math.max(Math.floor(dist / (brushSize.value / 4)), 1);\n\n  for (let i = 0; i &lt;= steps; i++) {\n    const t = i / steps;\n    const x = x0 + (x1 - x0) * t;\n    const y = y0 + (y1 - y0) * t;\n    drawBrushDirect(x, y);\n  }\n\n  scheduleRedraw();\n};\n\n// 直接绘制到遮罩层（不立即重绘整个canvas）\nconst drawBrushDirect = (x, y) =&gt; {\n  if (!maskCtx) return;\n\n  // 黑色遮罩\n  maskCtx.fillStyle = \"rgba(0, 0, 0, 1)\";\n\n  if (brushShape.value === \"circle\") {\n    // 圆形画笔\n    maskCtx.beginPath();\n    maskCtx.arc(x, y, brushSize.value / 2, 0, Math.PI * 2);\n    maskCtx.fill();\n  } else {\n    // 矩形画笔\n    const halfSize = brushSize.value / 2;\n    maskCtx.fillRect(\n      x - halfSize,\n      y - halfSize,\n      brushSize.value,\n      brushSize.value\n    );\n  }\n};\n\n// 单次绘制（用于点击）\nconst drawBrush = (x, y) =&gt; {\n  drawBrushDirect(x, y);\n  scheduleRedraw();\n};\n\nconst clearMask = () =&gt; {\n  if (!maskCtx) return;\n  maskCtx.clearRect(0, 0, maskCanvas.width, maskCanvas.height);\n  redraw();\n};\n\nconst confirmMask = () =&gt; {\n  // 创建遮罩图：原图 + alpha通道（ComfyUI格式）\n  // RGB通道保留原图，alpha通道表示遮罩（0=透明/需要替换，255=不透明/保留）\n  const resultCanvas = document.createElement(\"canvas\");\n  resultCanvas.width = maskCanvas.width;\n  resultCanvas.height = maskCanvas.height;\n  const resultCtx = resultCanvas.getContext(\"2d\");\n\n  // 1. 先绘制原始场景图作为底图\n  resultCtx.drawImage(image, 0, 0, resultCanvas.width, resultCanvas.height);\n\n  // 2. 获取遮罩层的像素数据\n  const maskImageData = maskCtx.getImageData(\n    0,\n    0,\n    maskCanvas.width,\n    maskCanvas.height\n  );\n  const maskData = maskImageData.data;\n\n  // 3. 获取结果画布的像素数据\n  const resultImageData = resultCtx.getImageData(\n    0,\n    0,\n    resultCanvas.width,\n    resultCanvas.height\n  );\n  const resultData = resultImageData.data;\n\n  // 4. 修改alpha通道：涂抹的区域设为透明（alpha=0，表示\"把产品放在这里\"）\n  for (let i = 0; i &lt; maskData.length; i += 4) {\n    // 如果遮罩层有内容（用户涂抹的区域）\n    if (maskData[i + 3] &gt; 0) {\n      // 将alpha通道设为0（透明），RGB保持原图\n      resultData[i + 3] = 0; // Alpha = 0 表示需要替换的区域\n    }\n    // 其他区域的alpha保持255（不透明），表示保留原图\n  }\n\n  // 5. 将处理后的数据写回画布\n  resultCtx.putImageData(resultImageData, 0, 0);\n\n  // 6. 生成最终的遮罩图（原图 + alpha通道遮罩）\n  const maskDataUrl = resultCanvas.toDataURL(\"image/png\");\n\n  emit(\"confirm\", {\n    mask: maskDataUrl,\n    width: resultCanvas.width,\n    height: resultCanvas.height,\n  });\n};\n\nconst cancelEdit = () =&gt; {\n  emit(\"cancel\");\n};\n&lt;/script&gt;\n\n&lt;style scoped&gt;\n.canvas-container {\n  display: inline-block;\n  max-width: 100%;\n  position: relative;\n}\n\ncanvas {\n  display: block;\n  max-width: 100%;\n  height: auto;\n}\n\n.brush-cursor {\n  transition: width 0.1s ease, height 0.1s ease;\n  z-index: 10;\n}\n\ninput[type=\"range\"] {\n  cursor: pointer;\n}\n\n/* 隐藏默认光标 */\n.cursor-none {\n  cursor: none;\n}\n&lt;/style&gt;\n</code></pre><h3>3.2 效果</h3><img class=\"editor-image\" src=\"/uploads/general/2025/11/6a636723d9e5def6ccb48ea606769ea2.png\" width=\"321\" height=\"381\" data-align=\"left\" style=\"width: 321px; height: 381px;\"><img class=\"editor-image\" src=\"/uploads/general/2025/11/9d6b6dee452301c58b850fad7fad4796.png\" width=\"320\" height=\"332\" data-align=\"left\" style=\"width: 320px; height: 332px;\"><p></p>', '文章介绍了ComfyUI在图像处理中的局限性，提出了利用HTML5的Canvas元素实现蒙版绘制工具的方案。该工具可简化流程、提高效率，通过Canvas API在网页上绘制图形和图像，实现交互式图像处理。文章以Vue组件为例，展示了如何使用Canvas绘制蒙版，并最终生成可用于图像处理的遮罩图。这一方法不仅提升了工作效率，还具有良好的兼容性和拓展性，为开发更多交互式应用提供了可能。', NULL, 1, 1, 96, 0, 1, 1, '2025-11-03 02:36:49', '2025-12-15 02:10:32', '2025-11-03 02:36:49', '2025-12-15 02:10:33');
INSERT INTO `posts` VALUES (9, '全栈开发通关秘籍：不啃硬书，玩着玩着就会了！', '<p>咱先掰扯清楚：全栈开发者不是 “啥都会点但啥都不精” 的半吊子，而是 “能自己从 0 到 1 搞出个小网站” 的狠人 —— 比如你想做个 “追星相册”，前端能划着看照片，后端能存图不丢，最后还能挂网上让好兄弟一起玩。这事儿听着酷，其实不用抱着厚书死磕，咱一步一步 “玩着学”！​</p><h3><strong>一、先搞懂：全栈不是 “全能超人”，是 “能串起整条线” 的人​</strong></h3><p>别被 “全栈” 俩字吓着！合格的全栈 er 就像 “奶茶店全能店员”：能点单（对接用户需求）、能做茶（写前端界面）、能囤料（搭后端存数据）、还能打包送出去（部署上线）—— 不用每步都做到 “行业 TOP”，但得能把 “点单到送茶” 的流程走通！​</p><p>避坑提醒：别学 “猴子掰玉米”！今天学 React，明天学 Java，后天又搞 Python，最后啥都没记住。先攥紧 1 套 “核心技能”，比如 “前端 Vue + 后端 Node.js”，玩熟了再解锁新技能～​</p><h3><strong>二、闯关模式：3 步从 “小白” 到 “能上线”​</strong></h3><p>全栈学习就像玩闯关游戏，先过第一关攒经验，再打下一关，稳得很！​</p><h4><strong>第一关：先搞定 “半边天”（3-6 个月）—— 选前端或后端，玩出成就感！​</strong></h4><p>推荐零基础先冲<strong>前端</strong>！毕竟写两行代码就能看到 “页面变样”，比对着黑屏写后端爽多了～​</p><p><strong>要是选前端：先玩会 “网页三件套”​</strong></p><ol><li><p><strong>HTML：给网页搭骨架​</strong></p></li></ol><p>不用记所有标签！先搞懂 “语义化”—— 比如用&lt;header&gt;当网页头，&lt;article&gt;装正文，就像给房间分 “客厅、卧室”，别全用&lt;div&gt;堆。​</p><blockquote><p><em>小玩法：给自己写个 “个人简介页”，放张自拍、写两句爱好，成就感拉满～</em>​</p></blockquote><ol start=\"2\"><li><p><strong>CSS：给骨架穿漂亮衣服​</strong></p></li></ol><p>重点玩会 Flex/Grid！用 Flex 让按钮 “居中”，用 Grid 把图片排成 “九宫格”，比瞎调margin快 10 倍。还能玩 CSS 动画 —— 让按钮 hover 时 “跳一下”，超有意思～​</p><blockquote><p><em>推荐工具：Can I Use（查 CSS 属性兼容性）、Codepen（看别人的炫酷效果，抄作业改改）</em>​</p></blockquote><ol start=\"3\"><li><p><strong>JavaScript：给衣服加 “魔法”​</strong></p></li></ol><p>不用死磕闭包、原型链！先学 “能让页面动起来” 的本事：比如点击按钮 “显示 / 隐藏自拍”，输入文字 “实时显示字数”。ES6 + 里先吃透Promise（解决 “回调地狱”，比如加载图片完再显示），够用了～​</p><blockquote><p><em>学习资源：B 站 “技术胖”（讲得像说相声）、MDN 的 “JavaScript 指南”（看不懂就跳，先玩例子）</em>​</p></blockquote><ol start=\"4\"><li><p><strong>框架选 1 个玩熟：Vue 或 React​</strong></p></li></ol><p>Vue 像 “傻瓜相机”，文档写得跟 “说明书” 似的，新手跟着敲 “ Todo 列表”（记待办事项），1 小时就能跑通；React 像 “单反相机”，稍微复杂点，但玩熟了能搞出更酷的效果（比如朋友圈那种下拉刷新）。​</p><blockquote><p><em>实战小目标：搞个 “追星相册前端”—— 能划着看爱豆照片，点照片看大图，搞定！</em>​</p></blockquote><p><strong>要是选后端：先玩会 “存数据 + 返数据”​</strong></p><p>选语言就像选奶茶：​</p><ul><li><p>想跟前端 “套近乎”：选 Node.js（都用 JS，不用换脑子），框架玩 Express—— 写个 “接收表单数据” 的接口，10 行代码搞定；​</p></li></ul><ul><li><p>想稳一点：选 Java（像经典美式，企业都爱用），玩 Spring Boot—— 跟着教程搞个 “用户登录”，输入账号密码能验证；​</p></li></ul><ul><li><p>想快一点：选 Python（像果茶，清爽好上手），玩 Flask—— 写个 “返回随机笑话” 的接口，5 分钟跑通。​</p></li></ul><p>数据库先玩 MySQL！不用学复杂的 “事务”“索引”，先搞懂 “增删改查”—— 比如存 “用户账号密码”，查 “谁登录了”，够用了～​</p><blockquote><p><em>实战小目标：搞个 “随机语录接口”—— 前端调用一下，能返回一句 “毒鸡汤”，成就感爆棚！</em>​</p></blockquote><h4><strong>第二关：打通 “前后端”（2-3 个月）—— 让它们 “聊起来”！​</strong></h4><p>第一关玩熟了，就该让前端和后端 “对话” 了！比如你前端搞了个 “登录框”，输入账号密码，得让后端 “验证对不对”，这步超关键～​</p><ol><li><p><strong>先搞懂 “HTTP 协议”：前后端的 “聊天方言”​</strong></p></li></ol><p>不用背所有状态码！记住 3 个就行：200（聊天成功）、404（后端没找到你要的东西）、500（后端自己崩了）。请求方法就记 GET（要数据，比如要语录）和 POST（发数据，比如发登录信息）。​</p><ol start=\"2\"><li><p><strong>解决 “跨域”：别让浏览器 “拦着聊天”​</strong></p></li></ol><p>前端调后端接口时，浏览器可能会蹦出 “跨域错误”，像保安拦着不让进门。简单招：后端加一句 “允许跨域” 的代码（比如 Node.js 里用cors插件），或者前端用 “代理”（Vue 里改个配置就行），分分钟搞定～​</p><ol start=\"3\"><li><p><strong>实战大任务：搞个 “摸鱼任务板”！​</strong></p></li></ol><p>这项目超实用，还能串起所有技能：​</p><ul><li><p>前端：用 Vue/React 做个页面，能加 “待办事项”（比如 “3 点摸鱼看剧”）、勾掉 “已完成”；​</p></li></ul><ul><li><p>后端：用 Node.js/Flask 写接口，接收前端的 “加任务”“改状态” 请求，存到 MySQL 里；​</p></li></ul><ul><li><p>关键：前端点 “加任务”，后端存好数据，再返回给前端显示 —— 这就通了！​</p></li></ul><blockquote><p><em>玩的时候可以加小彩蛋：比如完成 3 个任务，弹个 “摸鱼达人” 的弹窗～</em>​</p></blockquote><h4><strong>第三关：搞上线！让别人也能玩（1-2 个月）​</strong></h4><p>自己玩得爽不算，得让朋友也能打开你的 “摸鱼任务板”，这步超有成就感！​</p><ol><li><p><strong>Git：给代码整个 “时光机”​</strong></p></li></ol><p>写代码怕删错？用 Git！提交代码时写句备注（比如 “加了弹窗彩蛋”），删错了能回滚到之前的版本。远程仓库用 GitHub，把代码传上去，像存到 “云端硬盘”。​</p><blockquote><p><em>小技巧：记 3 个命令就行 ——git add .（选要提交的代码）、git commit -m \"备注\"（写备注）、git push（传云端）</em>​</p></blockquote><ol start=\"2\"><li><p><strong>部署：把项目 “搬上互联网”​</strong></p></li></ol><p>不用买贵服务器！新手推荐这俩：​</p><ul><li><p>前端静态页：Vercel（连 GitHub，push 代码自动部署，免费！）；​</p></li></ul><ul><li><p>全栈项目：Railway（上传代码就能跑，支持 Node.js/Python，免费额度够玩）；​</p></li></ul><p>要是想折腾，买个阿里云 ECS（学生机超便宜），学两句 Linux 命令（cd进文件夹、ls看文件），手动传代码也能成～​</p><ol start=\"3\"><li><p><strong>最后一步：搞个 “个性域名”​</strong></p></li></ol><p>部署完会有个 “随机域名”（比如 <a target=\"_blank\" rel=\"noopener noreferrer\" href=\"http://xxx.vercel.app\">xxx.vercel.app</a>），想换个酷的？去阿里云买个域名（比如 “<a target=\"_blank\" rel=\"noopener noreferrer\" href=\"http://moyu-task.top\">moyu-task.top</a>”，一年几十块），解析到你的项目，别人输域名就能玩你的 “摸鱼任务板” 啦！​</p><h3><strong>三、进阶：玩点 “高级活”（ optional ）​</strong></h3><p>要是觉得 “通关” 太简单，再解锁点新技能：​</p><ul><li><p>前端玩 SSR：用 Next.js/Nuxt.js 让页面加载更快，还能 SEO（比如 “摸鱼任务板” 能被百度搜到）；​</p></li></ul><ul><li><p>后端玩 Redis：给 “摸鱼任务” 加缓存，别人加载更快；​</p></li></ul><ul><li><p>跨平台：学 React Native，用前端代码写个 “摸鱼任务板” APP，手机也能玩～​</p></li></ul><h3><strong>四、避坑指南：别让 “挫败感” 劝退你！​</strong></h3><ol><li><p><strong>别死磕 “看不懂的知识点”​</strong></p></li></ol><p>比如学 JS 时卡 “闭包”，先跳过！等你写多了 “点击按钮改数据” 的代码，回头再看闭包，可能突然就懂了 —— 技术这东西，越玩越透～​</p><ol start=\"2\"><li><p><strong>多 “抄作业”，少 “空想”​</strong></p></li></ol><p>不会写 “登录功能”？去 GitHub 搜 “Vue 登录示例”，下载下来改改（把别人的 “用户名密码验证” 改成自己的），比自己瞎琢磨快 10 倍。​</p><ol start=\"3\"><li><p><strong>别怕 “bug”，bug 是 “经验包”​</strong></p></li></ol><p>写代码遇到 bug 很正常！比如 “前端调接口没反应”，先看控制台报错，再去 Google 搜 “Axios 没反应 解决”，慢慢就会 “猜 bug 在哪”—— 等你能快速修 bug，就离全栈不远了！​</p><p><strong>结语：全栈是 “玩出来的”，不是 “啃书啃出来的”​</strong></p><p>别把全栈想成 “高大上的技术活”，其实就是 “自己搞个小项目，从界面到上线，全流程玩一遍”。比如你想做个 “猫咪相册”，就从前端搭页面开始，再写后端存照片，最后部署上线 —— 玩着玩着，你就会发现：哦？原来我已经是全栈了！​</p><p>现在就动手：打开 VS Code，写第一行 HTML（<code>&lt;h1&gt;我的全栈之旅&lt;/h1&gt;</code>），通关开始！​</p>', '全栈开发通关秘籍：不啃硬书，玩着玩着就会了！', NULL, 1, 1, 211, 0, 1, 1, '2025-11-04 05:28:01', '2026-01-14 13:43:17', '2025-11-04 05:28:01', '2026-01-14 13:43:18');
INSERT INTO `posts` VALUES (11, 'Cloudflared：打造安全公网隧道的捷径', '<h3>一、下载与安装Cloudflared</h3><p>Cloudflared是Cloudflare提供的一款开源命令行工具，它能够通过Cloudflare的边缘网络创建隧道，将本地服务器安全地暴露到公网上。以下是下载和安装Cloudflared的步骤：</p><pre><code class=\"language-bash\">## 下载安装包\nwget https://ghfast.top/https://github.com/cloudflare/cloudflared/releases/latest/download/cloudflared-linux-amd64.deb\n\n## 安装\ndpkg -i cloudflared-linux-amd64.deb\n\n## 查看是否安装成功\ncloudflared -v</code></pre><p>上述命令通过<code>wget</code>下载了适用于Linux系统的Cloudflared安装包，并通过<code>dpkg</code>命令进行安装。检查安装成功后，用户即可开始配置隧道。</p><h3>二、安装网络工具</h3><p>为了管理和监控网络服务，可能需要安装额外的网络工具：</p><pre><code class=\"language-bash\">netstat -ntlp\n\nsudo apt update # 更新软件包列表\n\nsudo apt install net-tools # 安装 net-tools 工具包</code></pre><p><code>netstat</code>命令用于显示网络连接、路由表、接口统计等网络信息。若需要更详细地了解网络状态，<code>net-tools</code>是一个包含多个网络管理工具的软件包，如<code>ifconfig</code>。</p><h3>三、配置Cloudflared隧道</h3><p>安装完成后，可以通过以下命令创建一个到本地服务器的隧道：</p><pre><code class=\"language-bash\">cloudflared tunnel --url http://127.0.0.1:8434</code></pre><p>此命令指示<em>cloudflared</em>监听本地服务器的8434端口，并通过Cloudflare的边缘网络暴露该服务。以下是对该过程的详细解释：</p><ul><li><p><strong>本地服务器地址：</strong><code>http://127.0.0.1:8434</code> 表示本地服务器运行在8434端口上。</p></li><li><p><strong>Cloudflare隧道：</strong> 通过<code>--url</code>参数设置，Cloudflared会将所有到Cloudflare边缘节点的请求转发到这个地址。</p></li></ul><h3>四、背景知识与案例</h3><p>Cloudflare的隧道代理技术常用于以下场景：</p><ul><li><p><strong>远程访问：</strong> 开发者可以在家中安全地访问办公室内网的服务器。</p></li><li><p><strong>服务暴露：</strong> 对于没有公网IP的本地服务，可以通过Cloudflared快速地将其暴露到公网，接受外部请求。</p></li><li><p><strong>全球加速：</strong> 对于需要高可用性的服务，Cloudflare的全球边缘网络可以提供内容分发和负载均衡，提高访问速度。</p></li></ul><h3>五、延伸思考</h3><p>在使用Cloudflared时，应当注意以下几点：</p><ol><li><p><strong>安全性：</strong> 隧道通信使用了Cloudflare的加密技术，确保数据传输安全。</p></li><li><p><strong>性能考量：</strong> 考虑到网络延迟和带宽限制，应合理评估使用隧道代理对服务性能的影响。</p></li><li><p><strong>服务监控：</strong> 配置相应的监控工具，实时检查隧道状态和服务可用性。</p></li></ol><p>通过以上步骤，用户可以有效地利用Cloudflared为本地服务提供安全、高效的公网访问能力。</p>', '本文介绍了如何下载、安装和使用Cloudflared，一款通过Cloudflare边缘网络创建隧道，将本地服务器安全暴露至公网的开源工具。内容包括安装步骤、网络工具安装、隧道配置，以及Cloudflare隧道代理技术的应用场景和注意事项。强调其在安全性、性能考量和服务监控方面的价值，为用户提供了一种安全高效的公网访问解决方案。', NULL, 1, 1, 117, 0, 1, 1, '2025-11-12 13:15:27', '2026-01-18 09:23:56', '2025-11-12 13:15:27', '2026-01-18 09:23:56');
INSERT INTO `posts` VALUES (12, '前端性能优化九大策略', '<p>前端性能优化是提升用户体验和网站性能的重要环节。以下是一些前端性能优化的经验：</p><h3>代码层面：</h3><ol><li><p><strong>减少HTTP请求</strong>：合并CSS、JS文件，使用CSS Sprites将多张图片合成一张。</p></li><li><p><strong>代码压缩</strong>：使用工具如UglifyJS、CSSNano对JS和CSS进行压缩。</p></li><li><p><strong>懒加载</strong>：对于图片、视频等资源，可以在用户滚动到它们的位置时再加载。</p></li><li><p><strong>预加载</strong>：预测用户接下来可能访问的页面，提前加载相关资源。</p></li><li><p><strong>使用CDN</strong>：将静态资源放在CDN上，提高访问速度。</p></li><li><p><strong>避免重定向</strong>：减少301、302跳转，降低延迟。</p></li></ol><h3>网络层面：</h3><ol><li><p><strong>开启GZIP压缩</strong>：通过减少传输文件的大小来提高加载速度。</p></li><li><p><strong>使用HTTP/2</strong>：多路复用、服务器推送等特性可以进一步提高性能。</p></li><li><p><strong>合理设置HTTP缓存</strong>：利用浏览器缓存，减少重复资源的下载。</p></li></ol><h3>渲染层面：</h3><ol><li><p><strong>CSS放在头部，JS放在底部</strong>：避免CSS阻塞渲染，JS放在底部防止阻塞DOM解析。</p></li><li><p><strong>避免过多的DOM操作</strong>：DOM操作通常比JavaScript运算更慢，尽量减少DOM的读写操作。</p></li><li><p><strong>使用requestAnimationFrame优化动画</strong>：这可以让动画的更新与浏览器绘制保持同步，减少卡顿。</p></li><li><p><strong>减少重绘和回流</strong>：批量修改样式，使用文档片段等技术。</p></li></ol><h3>资源优化：</h3><ol><li><p><strong>优化图片</strong>：使用适当的格式（如WebP），压缩，懒加载。</p></li><li><p><strong>压缩字体和图标</strong>：使用字体的子集，仅包含必要的字符。</p></li><li><p><strong>精简第三方库</strong>：只引入需要的库和代码。</p></li></ol><h3>用户体验：</h3><ol><li><p><strong>交互反馈</strong>：对于长时间的操作，给予用户反馈，比如加载动画。</p></li><li><p><strong>首屏内容优化</strong>：确保首屏内容快速加载，提高用户体验。</p></li></ol><h3>工具和监控：</h3><ol><li><p><strong>使用性能分析工具</strong>：如Chrome DevTools的Performance、Lighthouse等。</p></li><li><p><strong>监控</strong>：使用性能监控工具，如New Relic或 Gomez，实时了解网站性能。</p></li><li><p><strong>A/B测试</strong>：对比不同优化策略的效果，选择最佳方案。</p></li></ol><p>前端性能优化是一个持续的过程，需要根据实际情况不断调整和优化。希望以上经验能对你有所帮助。</p>', '前端性能优化对提升用户体验至关重要。文章从代码、网络、渲染、资源优化和用户体验五个方面分享了优化策略，包括减少HTTP请求、代码压缩、懒加载、使用CDN、合理设置缓存、优化DOM操作、使用动画优化技术、图片和字体压缩等。同时强调了使用性能分析工具和监控的重要性，指出性能优化是一个持续的过程，需不断调整以实现最佳效果。这些经验旨在帮助开发者提高网站性能，改善用户体验。', NULL, 1, 1, 93, 0, 1, 1, '2025-11-17 12:52:32', '2026-01-17 09:12:47', '2025-11-17 12:52:32', '2026-01-17 09:12:48');
INSERT INTO `posts` VALUES (18, 'Andify-个人定制化AI编辑器', '<p>关注我的朋友可能发现，最近我的博客停更了——不是偷懒，是真的把所有业余时间都砸在了这款AI编辑器上。毕竟每次用Cursor等编辑器写东西，都要被固定模型、模糊token消耗、地区卡顿这三件事逼疯；试了圈CLI工具，又被Windows终端的各种bug劝退，索性干脆自己动手，造一款“懂用户痛点”的工具，也就是今天要和大家聊的Adnify。</p><p>顺便提一句，Adnify的内置提示词还参考了 <code>https://github.com/asgeirtj/system_prompts_leaks/</code> 这个<a target=\"_blank\" rel=\"noopener noreferrer\" href=\"https://github.com/asgeirtj/system_prompts_leaks/\">仓库</a>（在此谢谢作者的收集），在prompt优化上更贴合实际使用场景，不管是写代码还是写文案，都能更快get到你的需求～</p><p>说真的，做这款工具的初衷特别简单：就是想让自己（还有和我一样的朋友）用AI编辑时能<strong>“顺心点”</strong>——不用被模型绑架，不用为不明不白的消耗买单，更不用因为地区和终端问题闹心。所以Adnify从设计之初，就把<strong>“自由”和“透明”</strong>刻在了骨子里，对标Cursor却又精准解决了它的那些小遗憾。</p><p>如果你也经历过这些糟心时刻，那由adnaan开发、对标Cursor的桌面端AI编辑器Adnify，大概率会让你眼前一亮。它不是简单的功能堆砌，而是精准戳中痛点的<strong>“效率救星”</strong>，把被市面上编辑器偷走的选择权，重新交回你手里。</p><h3>✨ 拒绝“模型绑架”，云端+本地随心选</h3><p>市面上多数AI编辑器都像“封闭式花园”，只给你固定的1-2个模型选项：</p><ul><li><p>写代码需要的专业模型？没得选</p></li><li><p>日常创作的通用模型？只能被动接受</p></li></ul><p>而Adnify直接打破了这种限制：支持OpenAI、Gemini、Anthropic等主流云端模型一键接入，也能通过Ollama协议运行Qwen、Llama等本地模型，离线环境下照样能顺畅使用。写代码时用GPT-4保证精准度，处理敏感文档时切换到本地模型保障安全，同一对话中就能无缝切换，不用再在多个工具间来回跳转。</p><h3>💡 token消耗“明明白白”，告别黑盒焦虑</h3><p>相信很多人都有过这些灵魂拷问：</p><blockquote><p>“这篇文章生成到底花了多少token？”<br>“为什么明明没写多少内容，消耗却这么高？”</p></blockquote><p>市面上不少编辑器把token消耗藏在黑盒里，用户只能被动买单，连核对的机会都没有。</p><p>我们深知这种“未知焦虑”有多难受，所以adnaan在Adnify里特意加了实时统计功能：每一次生成、每一次修改对应的token消耗都清晰可见，还会自动生成月度统计报告。你可以精准掌控成本，再也不用为模糊的消耗明细买单。</p>', 'Andify-个人定制化AI编辑器', NULL, 1, 1, 69, 0, 1, 1, '2025-12-18 13:44:20', '2026-01-07 00:57:56', '2025-12-18 13:44:20', '2026-01-07 00:57:56');
INSERT INTO `posts` VALUES (19, 'Adnify：我开发的 AI 原生代码编辑器正式发布了！', '<blockquote><p>历时数日开发，Adnify 终于迎来了首个公开版本。这是一款将 AI 能力深度融入编辑器的桌面应用，希望能为开发者带来全新的编程体验。</p></blockquote><img class=\"editor-image\" src=\"/uploads/general/2025/12/961306d11d92bc5a4f508b5f06d550ee.png\" data-align=\"center\"><h2><strong>为什么要做 Adnify？</strong></h2><p>市面上的 AI 编辑器要么是 VS Code 插件形式，要么是纯 Web 应用。我想做一个<strong>原生桌面应用</strong>，让 AI 不只是一个聊天窗口，而是真正能理解代码、操作文件、执行命令的<strong>智能助手</strong>。</p><p>Adnify 的目标很简单：<strong>让 AI 成为你的编程搭档，而不是一个需要复制粘贴的问答机器人。</strong></p><h2><strong>核心特性</strong></h2><h3><strong>🤖 三种 AI 工作模式</strong></h3><img class=\"editor-image\" src=\"/uploads/general/2025/12/e6a213efd2e7d9e7d4f54042e98aefbf.png\" width=\"260\" height=\"579\" data-align=\"left\" style=\"width: 260px; height: 579px;\"><ul><li><p><strong>Chat 模式</strong>：纯对话，快速问答，不执行任何操作</p></li><li><p><strong>Agent 模式</strong>：AI 拥有完整的文件系统和终端权限，可以直接帮你写代码、运行命令</p></li><li><p><strong>Plan 模式</strong>：先规划再执行，适合复杂任务，每一步都可以审核</p></li></ul><h3><strong>🛠️ 22 个内置 AI 工具</strong></h3><p>AI 不只是能聊天，它可以：</p><table style=\"min-width: 50px;\"><colgroup><col style=\"min-width: 25px;\"><col style=\"min-width: 25px;\"></colgroup><tbody><tr><th colspan=\"1\" rowspan=\"1\"><p>工具</p></th><th colspan=\"1\" rowspan=\"1\"><p>功能</p></th></tr><tr><td colspan=\"1\" rowspan=\"1\"><p><code>read_file</code> / <code>write_file</code></p></td><td colspan=\"1\" rowspan=\"1\"><p>读写文件</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p><code>edit_file</code></p></td><td colspan=\"1\" rowspan=\"1\"><p>智能编辑，支持搜索替换</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p><code>run_command</code></p></td><td colspan=\"1\" rowspan=\"1\"><p>执行终端命令</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p><code>codebase_search</code></p></td><td colspan=\"1\" rowspan=\"1\"><p>语义搜索整个代码库</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p><code>go_to_definition</code></p></td><td colspan=\"1\" rowspan=\"1\"><p>跳转到定义</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p><code>find_references</code></p></td><td colspan=\"1\" rowspan=\"1\"><p>查找引用</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p><code>web_search</code></p></td><td colspan=\"1\" rowspan=\"1\"><p>联网搜索</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p>...</p></td><td colspan=\"1\" rowspan=\"1\"><p>还有更多</p></td></tr></tbody></table><h3><strong>⚡ 秒级启动</strong></h3><p>冷启动 <strong>&lt; 400ms</strong>，这对于一个 Electron 应用来说相当不错。主要优化：</p><ul><li><p>主进程窗口立即显示</p></li><li><p>延迟加载非关键模块</p></li><li><p>V8 代码缓存</p></li><li><p>React.lazy 组件懒加载</p></li><li><p>localStorage 缓存设置/主题/快捷键</p></li></ul><h3><strong>🎨 四套精心设计的主题</strong></h3><ul><li><p><strong>Adnify Dark</strong> - 默认深色主题，柔和护眼</p></li><li><p><strong>Midnight</strong> - 深邃午夜蓝</p></li><li><p><strong>Cyberpunk</strong> - 霓虹赛博朋克风</p></li><li><p><strong>Dawn</strong> - 明亮日间主题</p></li></ul><p>全局采用毛玻璃风格，配合流光边框和动态阴影。</p><h3><strong>📝 智能上下文引用</strong></h3><p>在对话中使用 <code>@</code> 引用上下文：</p><pre><code class=\"language-javascript\">@文件名     → 引用指定文件\n@codebase   → 语义搜索代码库\n@git        → 引用 Git 变更\n@terminal   → 引用终端输出\n@symbols    → 引用当前文件符号\n@web        → 启用网络搜索</code></pre><h3><strong>🔒 本地优先，隐私安全</strong></h3><ul><li><p>代码索引本地存储</p></li><li><p>支持 Ollama 本地模型</p></li><li><p>工作区隔离</p></li><li><p>敏感路径保护</p></li><li><p>命令白名单</p></li><li><p>完整审计日志</p></li></ul><h3><strong>⏪ 检查点系统</strong></h3><p>AI 操作前自动创建检查点，一键回滚到任意消息。大胆尝试，无后顾之忧。</p><h2><strong>技术栈</strong></h2><table style=\"min-width: 50px;\"><colgroup><col style=\"min-width: 25px;\"><col style=\"min-width: 25px;\"></colgroup><tbody><tr><th colspan=\"1\" rowspan=\"1\"><p>技术</p></th><th colspan=\"1\" rowspan=\"1\"><p>用途</p></th></tr><tr><td colspan=\"1\" rowspan=\"1\"><p>Electron 33</p></td><td colspan=\"1\" rowspan=\"1\"><p>桌面应用框架</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p>React 18</p></td><td colspan=\"1\" rowspan=\"1\"><p>UI 框架</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p>TypeScript 5</p></td><td colspan=\"1\" rowspan=\"1\"><p>类型安全</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p>Monaco Editor</p></td><td colspan=\"1\" rowspan=\"1\"><p>代码编辑器内核</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p>xterm.js</p></td><td colspan=\"1\" rowspan=\"1\"><p>终端模拟器</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p>Zustand</p></td><td colspan=\"1\" rowspan=\"1\"><p>状态管理</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p>LanceDB</p></td><td colspan=\"1\" rowspan=\"1\"><p>向量数据库（语义搜索）</p></td></tr></tbody></table><h2><strong>支持的 LLM</strong></h2><ul><li><p>OpenAI (GPT-4o, GPT-4, GPT-3.5)</p></li><li><p>Anthropic (Claude 3.5, Claude 3)</p></li><li><p>Google (Gemini Pro, Gemini Flash)</p></li><li><p>DeepSeek</p></li><li><p>Ollama (本地模型)</p></li><li><p>自定义 API</p></li></ul><h2><strong>下载</strong></h2><p><strong>GitHub</strong>: <a target=\"_blank\" rel=\"noopener noreferrer\" href=\"https://github.com/adnaan-worker/adnify/releases\">https://github.com/adnaan-worker/adnify/releases</a></p><p><strong>Gitee 镜像</strong>: <a target=\"_blank\" rel=\"noopener noreferrer\" href=\"https://gitee.com/adnaan/adnify/releases\">https://gitee.com/adnaan/adnify/releases</a></p><p>支持 Windows、macOS、Linux 三大平台。</p><h2><strong>开源协议</strong></h2><p>Apache 2.0 - 完全开源，欢迎贡献代码！</p><hr><h2><strong>后续计划</strong></h2><ul><li><p>[ ] 插件系统</p></li><li><p>[ ] 多语言 LSP 支持扩展</p></li><li><p>[ ] 协作编辑</p></li><li><p>[ ] 更多 AI 模型支持</p></li></ul><hr><p>如果你觉得这个项目有意思，欢迎 Star ⭐ 支持一下！</p><p>有任何问题或建议，可以在 GitHub Issues 中反馈，或者发邮件到 <a target=\"_blank\" rel=\"noopener noreferrer\" href=\"mailto:adnaan.worker@gmail.com\">adnaan.worker@gmail.com</a>。</p><p><strong>项目地址</strong>：</p><ul><li><p>GitHub: <a target=\"_blank\" rel=\"noopener noreferrer\" href=\"https://github.com/adnaan-worker/adnify\">https://github.com/adnaan-worker/adnify</a></p></li><li><p>Gitee: <a target=\"_blank\" rel=\"noopener noreferrer\" href=\"https://gitee.com/adnaan/adnify\">https://gitee.com/adnaan/adnify</a></p></li><li><p>官网: <a target=\"_blank\" rel=\"noopener noreferrer\" href=\"https://adnify-website.vercel.app\">https://adnify-website.vercel.app</a></p></li></ul><p></p>', '一个定制化极高的编辑器', NULL, 1, 1, 108, 0, 1, 1, '2025-12-29 13:31:50', '2026-01-21 11:41:57', '2025-12-29 13:31:50', '2026-01-21 11:41:58');
INSERT INTO `posts` VALUES (20, 'Adnify支持mcp啦！', '<p>经过几天时间的打磨，mcp正式上线</p><p>大家可下载最新版本体验，在设置-&gt;MCP下可以添加多种内置mcp工具，页可以添加自定义的mcp</p><blockquote><p>软件最新版一般会最新同步到github，gitee可能同步不及时，大家可以访问github下载</p></blockquote><img class=\"editor-image\" src=\"/uploads/general/2026/01/c5d8bf8159bfcd14189c7984ff52bdd1.png\" width=\"1200\" height=\"650\" data-align=\"center\" style=\"width: 1200px; height: 650px;\"><img class=\"editor-image\" src=\"/uploads/general/2026/01/68d9a116f66ff127e29ce76ffc8d12b6.png\" width=\"1200\" height=\"650\" data-align=\"center\" style=\"width: 1200px; height: 650px;\"><img class=\"editor-image\" src=\"/uploads/general/2026/01/4562a8afcc4c553627c41adaa8cc6329.png\" width=\"257\" height=\"510\" data-align=\"left\" style=\"width: 257px; height: 510px;\"><img class=\"editor-image\" src=\"/uploads/general/2026/01/10ac2f4892f30c439f73ad920083d918.png\" width=\"258\" height=\"412\" data-align=\"left\" style=\"width: 258px; height: 412px;\"><p></p>', NULL, NULL, 1, 1, 68, 0, 1, 1, '2026-01-01 13:59:32', '2026-01-07 12:06:57', '2026-01-01 13:59:32', '2026-01-07 12:06:57');
INSERT INTO `posts` VALUES (21, '本人讨厌将开源项目进行魔改商用', '<p>非常讨厌未经允许将开源项目进行魔改，隐藏原作者版权、仓库地址拿去商用的行为。</p>', NULL, NULL, 1, 1, 31, 0, 3, 1, '2026-01-08 02:56:42', '2026-01-22 07:50:02', '2026-01-08 02:56:42', '2026-01-22 07:50:02');
INSERT INTO `posts` VALUES (22, '新功能内测中！', '<p>近期正在深入研究 Plan 工作流，旨在构建一种交互式需求确认机制，在开发过程中多次询问用户，逐步明确复杂任务的具体需求，从而确保最终交付成果的完整性。</p><p>同时，项目还强化了 UI/UX 设计角色，能够生成更具自然感、避免“AI 痕迹”的界面设计方案。以下为部分功能截图，模型采用小米的 MiMo-V2-Flash。</p><img class=\"editor-image\" src=\"/uploads/general/2026/01/d1a65866be5b4347bf2620d9bf594bf1.png\" data-align=\"center\"><p></p><img class=\"editor-image\" src=\"/uploads/general/2026/01/8c9c10d328da9cf0aa29afc9184cff62.png\" data-align=\"center\"><p></p><img class=\"editor-image\" src=\"/uploads/general/2026/01/6fdb2bf4dad38ebd24afa9f056eb4eb4.png\" data-align=\"center\"><p></p><img class=\"editor-image\" src=\"/uploads/general/2026/01/d0e198cb0a062c9df8f3d16af99ae105.png\" data-align=\"center\"><img class=\"editor-image\" src=\"/uploads/general/2026/01/3afc381dbb4d364153c308e961741c91.png\" data-align=\"center\"><p></p>', '该研究聚焦于开发“Plan”工作流，核心目标是建立一套交互式需求确认机制。该机制通过在开发过程中多次与用户互动，逐步细化并明确复杂任务的具体需求，从而有效保障最终交付成果的完整性与准确性。项目同时强调了UI/UX设计的重要性，致力于生成视觉效果更自然、能够巧妙规避“AI痕迹”的界面方案。目前项目已取得阶段性成果，并采用了小米的MiMo-V2-Flash模型，附有相关功能截图予以展示。', NULL, 1, 1, 45, 0, 1, 1, '2026-01-11 15:23:20', '2026-01-18 05:20:47', '2026-01-11 15:23:20', '2026-01-18 05:20:48');
INSERT INTO `posts` VALUES (23, 'Adnify近日更新日志', '<blockquote><p>每一次更新，都是一杯新泡的茶 ☕</p></blockquote><p>所有重要更改都会记录在此文件中。格式基于 <a target=\"_blank\" rel=\"nofollow\" href=\"https://keepachangelog.com/\"><u>Keep a Changelog</u></a>，版本号遵循 <a target=\"_blank\" rel=\"nofollow\" href=\"https://semver.org/\"><u>Semantic Versioning</u></a>。</p><h2><strong>贡献者 | Contributors</strong></h2><p>感谢所有为 Adnify 做出贡献的开发者！你们是最棒的 🎉</p><p><img class=\"editor-image\" src=\"https://github.com/adnaan-worker.png\" alt=\"adnaan\" width=\"50\" height=\"50\" data-display=\"inline\" data-align=\"left\" style=\"height: 50px; width: 50px;\"><img class=\"editor-image\" src=\"https://github.com/kerwin2046.png\" alt=\"kerwin\" width=\"50\" height=\"50\" data-display=\"inline\" data-align=\"left\" style=\"height: 50px; width: 50px;\"></p><p><strong>[1.5.13] - 2026-01-15 ☕ 泡了杯龙井，修了个终端</strong></p><blockquote><p>\"终端空白？不存在的。\" —— 某位不愿透露姓名的开发者</p></blockquote><h3><strong>✨ 新功能</strong></h3><ul><li><p>⚙️ <strong>MCP 自动连接开关</strong> - 终于可以控制 MCP 服务器是否自动连接了，不想连就不连，任性！</p></li></ul><h3><strong>🐛 Bug 修复</strong></h3><ul><li><p>🖥️ <strong>终端空白问题</strong> - 切换工作区后终端不再装死，乖乖显示内容</p></li><li><p>🔧 <strong>PTY 创建检查</strong> - 修复了一个\"我以为成功了但其实没有\"的尴尬 bug</p></li></ul><h3><strong>🚀 性能优化</strong></h3><ul><li><p>⚡ <strong>启动加速</strong> - MCP 服务改为延迟初始化，启动快了那么一丢丢</p></li><li><p>🧹 <strong>代码瘦身</strong> - 清理了一堆\"为了兼容而存在\"的代码，轻装上阵</p></li></ul><hr><h2><strong>[1.5.12] - 2026-01-15 🔍 搜索引擎大换血</strong></h2><blockquote><p>告别 Serper，拥抱 Google PSE，省钱又好用</p></blockquote><h3><strong>✨ 新功能</strong></h3><ul><li><p>🔄 <strong>检查点回滚增强</strong> - 回滚时连图片和上下文都给你恢复，贴心不？</p></li><li><p>🔍 <strong>网络搜索重构</strong> - Google PSE + DuckDuckGo 双引擎，搜啥都行</p></li><li><p>⚙️ <strong>搜索配置界面</strong> - 设置里就能配 Google API，不用改代码了</p></li><li><p>🌐 <strong>Jina Reader 集成</strong> - read_url 现在能读 JS 渲染的页面了，SPA 也不怕</p></li></ul><h3><strong>🐛 Bug 修复</strong></h3><ul><li><p>� <strong>表格渲染f</strong> - AI 输出的表格终于正常显示了 (感谢 @kerwin)</p></li></ul><h3><strong>🚀 优化</strong></h3><ul><li><p>⬆️ <strong>Electron 39</strong> - 升级框架，修复安全漏洞</p></li><li><p>� <em>持</em>搜索提示优化** - 教会 AI 一次搜完，别分三次</p></li><li><p>⏱️ <strong>超时调整</strong> - read_url 默认 60 秒，慢网站也能抓</p></li></ul><h3><strong>🔧 重构</strong></h3><ul><li><p>🧠 <strong>压缩管理器</strong> - 上下文压缩逻辑整合，代码更清爽</p></li></ul><hr><h2><strong>[1.5.11] - 2026-01-15 🛡️ 类型安全加固</strong></h2><blockquote><p>把 any 赶出代码库的一天</p></blockquote><h3><strong>� Bug 修复</strong></h3><ul><li><p>🔧 <strong>跨平台兼容</strong> - Performance 类型问题搞定</p></li><li><p>� <strong>依赖同改步</strong> - package-lock.json 终于和 package.json 对上了</p></li></ul><h3><strong>🔧 重构</strong></h3><ul><li><p>🛡️ <strong>类型安全</strong> - 移除不安全的类型断言 (感谢 @kerwin)</p></li><li><p>🧪 <strong>测试重组</strong> - 测试结构更清晰，覆盖更全面</p></li></ul><hr><h2><strong>[1.5.10] - 2026-01-14 ✨ 富文本来了</strong></h2><blockquote><p>Agent 的输出终于不只是纯文本了</p></blockquote><h3><strong>✨ 新功能</strong></h3><ul><li><p>🎨 <strong>富文本支持</strong> - Agent 工具执行结果支持多种格式</p></li></ul><h3><strong>�类 Bug 修复</strong></h3><ul><li><p>🔇 <strong>生产环境静音</strong> - 控制台不再刷屏</p></li><li><p>⏱️ <strong>更新检查</strong> - 不再无限等待 (#12)</p></li></ul><h3><strong>🔧 重构</strong></h3><ul><li><p>🛡️ <strong>类型改进</strong> - 又干掉了一批 any (感谢 @kerwin)</p></li></ul><hr><h2><strong>[1.5.9] - 2026-01-14 📟 终端进化</strong></h2><blockquote><p>终端现在会告诉你它怎么了</p></blockquote><h3><strong>✨ 新功能</strong></h3><ul><li><p>📟 <strong>终端事件</strong> - PTY 退出和错误都有事件通知了</p></li></ul><h3><strong>🐛 Bug 修复</strong></h3><ul><li><p>⏱️ <strong>更新检查</strong> - 修复挂起问题</p></li><li><p>🔧 <strong>路径处理</strong> - 更健壮的验证和日志</p></li></ul><h3><strong>🚀 优化</strong></h3><ul><li><p>🍎 <strong>CI 发布</strong> - macOS arm64 文件名统一</p></li></ul><hr><h2><strong>[1.5.8] - 2026-01-14 🔒 安全小补丁</strong></h2><h3><strong>🐛 Bug 修复</strong></h3><ul><li><p>� <strong>路径验证</strong> - 更严格的文件处理</p></li></ul><hr><h2><strong>[1.5.7] - 2026-01-14 🔀 Git 分支侦探</strong></h2><blockquote><p>分支检测失败？我有 Plan B！</p></blockquote><h3><strong>� Bug 修复</strong></h3><ul><li><p>🔀 <strong>Git 分支检测</strong> - 添加回退方法，再也不会显示 HEAD 了</p></li><li><p>🐛 <strong>提示词预览</strong> - MiniMax 2.1 think 标签显示正常了 (感谢 @kerwin)</p></li></ul><h3><strong>🔧 重构</strong></h3><ul><li><p>🏗️ <strong>工具执行优化</strong> - 审批流程和快照管理</p></li><li><p>�️ A<strong>类型安全</strong> - 继续消灭 any (感谢 @kerwin)</p></li><li><p>📝 <strong>日志统一</strong> - console 全换成 Logger (感谢 @kerwin)</p></li></ul><hr><h2><strong>[1.5.6] - 2026-01-14 🛠️ Agent 大重构</strong></h2><blockquote><p>代码量减少了，功能却更强了</p></blockquote><h3><strong>✨ 新功能</strong></h3><ul><li><p>🛠️ <strong>审批工作流</strong> - 工具执行前可以审批了</p></li><li><p>🎯 <strong>动态工具过滤</strong> - 根据模式自动过滤可用工具</p></li><li><p>� <em>复</em>Agent 指南** - 工具使用文档更完善</p></li></ul><h3><strong>🔧 重构</strong></h3><ul><li><p>🏗️ <strong>Agent 架构</strong> - 核心循环和上下文压缩重组</p></li><li><p>🧠 <strong>压缩管理器</strong> - 统一管理，统计更清晰</p></li><li><p>📋 <strong>Prompt 系统</strong> - 类型定义整合</p></li></ul><h3><strong>🐛 Bug 修复</strong></h3><ul><li><p>🐛 <strong>提示词预览</strong> - 显示问题修复</p></li><li><p>� <strong>Git 分支</strong> - 不再显示 HEAD</p></li></ul><hr><h2><strong>[1.5.5] - 2026-01-13 📖 文档日</strong></h2><h3><strong>✨ 新功能</strong></h3><ul><li><p>📖 <strong>Agent 指南</strong> - 工具使用文档更完善</p></li></ul><h3><strong>� Bulg 修复</strong></h3><ul><li><p>🔧 <strong>Monaco 类型</strong> - 配置覆盖说明 (感谢 @kerwin)</p></li></ul><hr><h2><strong>[1.5.4] - 2026-01-12 🤖 AI 能力升级</strong></h2><blockquote><p>更聪明的 Agent，更好用的工具</p></blockquote><h3><strong>✨ 新功能</strong></h3><ul><li><p>🤖 <strong>文件处理增强</strong> - Agent 更懂文件操作了</p></li><li><p>� <strong>Google AI SDK</strong> - 消息处理更强</p></li><li><p>🎨 <strong>GPT Tokenizer</strong> - 上下文管理更精准</p></li><li><p>📥 <strong>API 导入向导</strong> - 配置解析更智能</p></li><li><p>🎯 <strong>ask_user 工具</strong> - 计划模式工作流指南</p></li></ul><h3><strong>� 重构：</strong></h3><ul><li><p>🛡️ <strong>TypeScript 优化</strong> - 类型守卫加持 (感谢 @kerwin)</p></li><li><p>⚡ <strong>App 性能</strong> - 组件优化 (感谢 @kerwin)</p></li></ul><h3><strong>🐛 Bug 修复</strong></h3><ul><li><p>🔧 <strong>更新安装</strong> - 日志和延迟执行优化</p></li><li><p>📦 <strong>CI 发布</strong> - 多架构元数据处理</p></li></ul><hr><h2><strong>[1.5.2] - 2026-01-12 📚 社区建设</strong></h2><h3><strong>✨ 新功能</strong></h3><ul><li><p>� <strong>贡献系指南</strong> - 欢迎来贡献代码！</p></li></ul><hr><h2><strong>[1.5.1] - 2026-01-10 🔧 稳定性修复</strong></h2><h3><strong>🐛 Bug 修复</strong></h3><ul><li><p>� <strong>CI 内存溢出</strong> - 降级 electron-builder 确保稳定</p></li><li><p>🎨 <strong>Regenerate 按钮</strong> - 位置和国际化修复</p></li><li><p>📝 <strong>外部修改对话框</strong> - AI 编辑后不再误报</p></li><li><p>🔌 <strong>Monaco API</strong> - v0.55 兼容性修复</p></li></ul><hr><h2><strong>[1.5.0] - 2026-01-10 🎉 自动更新上线！</strong></h2><blockquote><p>终于不用手动下载了</p></blockquote><h3><strong>✨ 新功能</strong></h3><ul><li><p>🔄 <strong>自动更新</strong> - 安装版自动下载安装，便携版提示下载</p></li><li><p>🧠 <strong>4 级压缩</strong> - L4 自动切换新会话并携带摘要</p></li><li><p>� <strong>压缩可视化</strong> `- 状态栏显示压缩级别和动画</p></li></ul><p></p>', 'Adnify项目近期发布了多个版本更新（1.5.0至1.5.13），重点提升了功能、性能和稳定性。核心改进包括：引入自动更新机制，优化终端体验（修复空白问题，增加事件通知），重构Agent架构（增强工具审批流程和动态过滤），并大幅提升类型安全性以消除代码隐患。此外，搜索引擎切换为Google PSE与DuckDuckGo双引擎，集成Jina Reader以支持JS渲染页面抓取，并新增富文本支持使Agent输出更丰富。项目遵循Keep a Changelog和Semantic Versioning规范，持续进行代码瘦身和性能优化，感谢开发者的贡献。', NULL, 1, 1, 92, 0, 2, 1, '2026-01-15 13:15:30', '2026-01-21 11:11:51', '2026-01-15 13:15:30', '2026-01-21 11:40:17');

-- ----------------------------
-- Table structure for projects
-- ----------------------------
DROP TABLE IF EXISTS `projects`;
CREATE TABLE `projects`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '项目ID',
  `title` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '项目标题',
  `slug` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'URL友好标识',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '项目简介',
  `content` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '项目详细介绍(支持Markdown)',
  `cover_image` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '项目封面图',
  `icon` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '项目图标',
  `status` enum('active','archived','developing','paused') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'developing' COMMENT '项目状态',
  `visibility` enum('public','private') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'public' COMMENT '可见性',
  `language` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '主要编程语言',
  `language_color` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '语言颜色(十六进制)',
  `tags` json NULL COMMENT '项目标签数组',
  `tech_stack` json NULL COMMENT '技术栈数组',
  `features` json NULL COMMENT '项目特性数组',
  `github_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'GitHub仓库地址',
  `gitee_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'Gitee仓库地址',
  `demo_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '在线演示地址',
  `docs_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '文档地址',
  `npm_package` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'NPM包名',
  `stars` int NULL DEFAULT 0 COMMENT 'Star数量',
  `forks` int NULL DEFAULT 0 COMMENT 'Fork数量',
  `watchers` int NULL DEFAULT 0 COMMENT 'Watch数量',
  `issues` int NULL DEFAULT 0 COMMENT '问题数量',
  `downloads` int NULL DEFAULT 0 COMMENT '下载量(NPM等)',
  `is_featured` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否精选展示',
  `is_open_source` tinyint(1) NOT NULL DEFAULT 1 COMMENT '是否开源',
  `display_order` int NULL DEFAULT 0 COMMENT '显示排序(数值越大越靠前)',
  `author_id` int NOT NULL COMMENT '创建者ID(管理员)',
  `view_count` int NULL DEFAULT 0 COMMENT '浏览次数',
  `started_at` date NULL DEFAULT NULL COMMENT '项目开始日期',
  `last_updated_at` datetime NULL DEFAULT NULL COMMENT '最后更新时间',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_slug`(`slug` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE,
  INDEX `idx_visibility`(`visibility` ASC) USING BTREE,
  INDEX `idx_is_featured`(`is_featured` ASC) USING BTREE,
  INDEX `idx_display_order`(`display_order` DESC) USING BTREE,
  INDEX `idx_created_at`(`created_at` DESC) USING BTREE,
  INDEX `idx_author_id`(`author_id` ASC) USING BTREE,
  INDEX `idx_projects_status_order`(`status` ASC, `display_order` ASC, `created_at` DESC) USING BTREE COMMENT '项目状态排序索引',
  INDEX `idx_projects_status`(`status` ASC) USING BTREE,
  INDEX `idx_projects_view_count`(`view_count` DESC) USING BTREE,
  INDEX `idx_projects_created_at`(`created_at` DESC) USING BTREE,
  FULLTEXT INDEX `ft_search`(`title`, `description`),
  FULLTEXT INDEX `ft_projects_search`(`title`, `description`) WITH PARSER `ngram` COMMENT '项目全文搜索索引',
  CONSTRAINT `fk_projects_author_id` FOREIGN KEY (`author_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE = InnoDB AUTO_INCREMENT = 55 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '项目表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of projects
-- ----------------------------
INSERT INTO `projects` VALUES (44, '光阴副本-个人博客前端（React版本）', 'adnaan-blog-frontend', '光阴副本博客项目基于 React + TypeScript 构建，用于记录个人学习过程及心得。前端利用组件化开发与 TypeScript 静态类型检查，搭配 React Router、Redux 等实现高效交互与状态管理。项目具备笔记 - 简短的学习笔记和心得，时光 - 按时间线展示的内容记录，思考 - 深度思考和观点分享，关于 - 个人介绍和联系方式等功能，致力于打造便捷的技术分享交流平台。', '<p style=\"text-align: left;\">🔥 <strong>核心亮点</strong>: AI写作助手 + 实时聊天 + 智能推荐 + 全栈架构 + 移动优先设计</p><p style=\"text-align: left;\">💡 <strong>技术前沿</strong>: React 19 + Node.js + MySQL + Redis + <a target=\"_blank\" rel=\"noopener noreferrer\" href=\"http://Socket.IO\">Socket.IO</a> + LangChain + OpenAI</p><h2 style=\"text-align: left;\"><strong>🖼️ 运行效果</strong></h2><p style=\"text-align: left;\"></p><img class=\"editor-image\" src=\"/uploads/general/2025/10/8510531e26ac6931ac0bf9fdc8fc24b5.png\" data-align=\"center\"><h2 style=\"text-align: left;\"><strong>🎯 立即体验</strong></h2><blockquote><p><strong>🚀 在线演示</strong>: <a target=\"_blank\" rel=\"noopener noreferrer\" href=\"http://www.adnaan.cn\">http://www.adnaan.cn</a></p><p><strong>📱 移动端</strong>: 完美适配手机、平板、桌面</p><p><strong>🤖 AI功能</strong>: 智能写作、实时聊天、内容分析</p><p><strong>⚡ 性能</strong>: 首屏加载&lt;1s，60fps流畅动画</p></blockquote><h3 style=\"text-align: left;\"><strong>🔥 热门功能</strong></h3><ul><li><p><strong>AI写作助手</strong> - 让AI帮你写文章，创作效率提升10倍</p></li><li><p><strong>实时聊天</strong> - 与AI助手实时对话，获得智能建议</p></li><li><p><strong>智能推荐</strong> - 基于你的兴趣，推荐最相关的内容</p></li><li><p><strong>移动优先</strong> - 完美适配所有设备，随时随地创作</p></li><li><p><strong>实时同步</strong> - 多端数据实时同步，永不丢失</p></li></ul><h2 style=\"text-align: left;\"><strong>🌟 为什么选择 adnaan的博客呢？</strong></h2><h3 style=\"text-align: left;\"><strong>🎯 AI驱动的智能写作</strong></h3><ul><li><p>🤖 <strong>AI写作助手</strong> - 基于GPT的智能内容生成，让创作更高效</p></li><li><p>📝 <strong>智能润色</strong> - 自动语法检查、风格优化、内容建议</p></li><li><p>🏷️ <strong>智能标签</strong> - AI自动提取关键词、生成标签、分类建议</p></li><li><p>📊 <strong>内容分析</strong> - 自动生成文章摘要、阅读时间预估、可读性评分</p></li></ul><h3 style=\"text-align: left;\"><strong>⚡ 实时互动体验</strong></h3><ul><li><p>💬 <strong>实时聊天</strong> - <a target=\"_blank\" rel=\"noopener noreferrer\" href=\"http://基于Socket.IO\">基于Socket.IO</a>的即时通讯系统</p></li><li><p>🔔 <strong>实时通知</strong> - 点赞、评论、关注等实时推送</p></li><li><p>👥 <strong>在线用户</strong> - 显示当前在线用户，增强社区感</p></li><li><p>🎮 <strong>互动游戏</strong> - 内置小游戏，增加用户粘性</p></li></ul><h3 style=\"text-align: left;\"><strong>🎨 极致视觉体验</strong></h3><ul><li><p>🌈 <strong>动态主题</strong> - 支持自定义主题色彩，实时预览</p></li><li><p>✨ <strong>微动画</strong> - 60fps流畅动画，每个细节都精心设计</p></li><li><p>📱 <strong>移动优先</strong> - 完美适配所有设备，触摸体验优化</p></li><li><p>🎭 <strong>深色模式</strong> - 护眼深色主题，自动切换</p></li></ul><h3 style=\"text-align: left;\"><strong>🚀 性能与安全</strong></h3><ul><li><p>⚡ <strong>极速加载</strong> - Vite构建，首屏加载&lt;1s</p></li><li><p>🔒 <strong>企业级安全</strong> - JWT认证、密码加密、XSS防护</p></li><li><p>📈 <strong>高并发</strong> - Redis缓存、数据库优化、CDN加速</p></li><li><p>🔄 <strong>实时同步</strong> - 多端数据实时同步，永不丢失</p></li></ul><h3 style=\"text-align: left;\"><strong>🛠️ 开发者天堂</strong></h3><ul><li><p>📚 <strong>完整文档</strong> - Swagger API文档，零学习成本</p></li><li><p>🎯 <strong>TypeScript</strong> - 100%类型安全，开发效率翻倍</p></li><li><p>🔧 <strong>一键部署</strong> - Docker容器化，一键部署到任何平台</p></li><li><p>📦 <strong>模块化</strong> - 高度解耦，易于扩展和维护</p></li></ul><h2 style=\"text-align: left;\"><strong>🚀 核心功能展示</strong></h2><h3 style=\"text-align: left;\"><strong>🏠 智能首页 - 个性化内容推荐</strong></h3><ul><li><p>🎯 <strong>智能推荐</strong> - 基于用户行为的个性化内容推荐</p></li><li><p>📊 <strong>实时数据</strong> - 文章数量、浏览量、用户活跃度实时统计</p></li><li><p>🔍 <strong>智能搜索</strong> - 全文搜索、标签搜索、AI语义搜索</p></li><li><p>📱 <strong>响应式设计</strong> - 完美适配手机、平板、桌面所有设备</p></li></ul><h3 style=\"text-align: left;\"><strong>📝 AI写作系统 - 让创作更智能</strong></h3><ul><li><p>✍️ <strong>富文本编辑</strong> - 支持图片、视频、代码块、表格等丰富内容</p></li><li><p>🤖 <strong>AI写作助手</strong> - 智能续写、内容优化、风格调整</p></li><li><p>🏷️ <strong>智能标签</strong> - AI自动提取关键词、生成标签、分类建议</p></li><li><p>💾 <strong>版本控制</strong> - 文章版本历史、自动保存、恢复功能</p></li><li><p>📈 <strong>数据分析</strong> - 阅读时间预估、可读性评分、SEO优化建议</p></li></ul><h3 style=\"text-align: left;\"><strong>💬 实时互动 - 让交流更生动</strong></h3><ul><li><p>💬 <strong>实时聊天</strong> - <a target=\"_blank\" rel=\"noopener noreferrer\" href=\"http://基于Socket.IO\">基于Socket.IO</a>的即时通讯系统</p></li><li><p>🔔 <strong>智能通知</strong> - 点赞、评论、关注等实时推送</p></li><li><p>👥 <strong>在线用户</strong> - 显示当前在线用户，增强社区感</p></li><li><p>🎮 <strong>互动游戏</strong> - 内置小游戏，增加用户粘性</p></li><li><p>📱 <strong>移动优化</strong> - 完美的移动端聊天体验</p></li></ul><h3 style=\"text-align: left;\"><strong>📖 智能手记 - 记录生活的美好</strong></h3><ul><li><p>😊 <strong>心情记录</strong> - 支持心情标签、天气、地点、音乐记录</p></li><li><p>🔒 <strong>私密内容</strong> - 个人私密手记，支持公开/私密切换</p></li><li><p>🏷️ <strong>智能标签</strong> - AI自动分类、标签推荐</p></li><li><p>📅 <strong>时间线</strong> - 按时间顺序展示手记内容</p></li><li><p>🔍 <strong>智能搜索</strong> - 快速查找历史手记，支持语义搜索</p></li></ul><h3 style=\"text-align: left;\"><strong>🤖 AI智能助手 - 你的专属AI伙伴</strong></h3><ul><li><p>💡 <strong>智能写作</strong> - AI辅助内容生成和优化</p></li><li><p>🗣️ <strong>智能聊天</strong> - 基于LangChain的对话系统</p></li><li><p>📊 <strong>内容分析</strong> - 自动提取关键词、生成摘要</p></li><li><p>⚡ <strong>批量处理</strong> - 异步任务队列，支持大批量操作</p></li><li><p>💰 <strong>配额管理</strong> - 用户使用配额和限制管理</p></li></ul><h3 style=\"text-align: left;\"><strong>👤 个人中心 - 你的数字身份</strong></h3><ul><li><p>🎨 <strong>个性化资料</strong> - 个人信息、头像、简介、主题定制</p></li><li><p>📈 <strong>数据统计</strong> - 个人数据可视化展示，成长轨迹</p></li><li><p>🏆 <strong>成就系统</strong> - 用户等级、徽章、成就解锁</p></li><li><p>📁 <strong>文件管理</strong> - 个人文件上传、存储管理、批量操作</p></li><li><p>🔔 <strong>消息中心</strong> - 系统通知、私信、评论回复</p></li></ul><h3 style=\"text-align: left;\"><strong>🛠️ 开发者工具 - 程序员的最爱</strong></h3><ul><li><p>🎨 <strong>代码高亮</strong> - 支持100+编程语言语法高亮</p></li><li><p>📋 <strong>代码复制</strong> - 一键复制代码到剪贴板</p></li><li><p>🔤 <strong>专业字体</strong> - 专业代码字体栈配置</p></li><li><p>📚 <strong>API文档</strong> - 完整的Swagger API文档</p></li><li><p>🔧 <strong>代码格式化</strong> - 一键格式化代码，统一代码风格</p></li></ul><h2 style=\"text-align: left;\"><strong>🎨 设计特色</strong></h2><h3 style=\"text-align: left;\"><strong>主题系统</strong></h3><ul><li><p><strong>CSS变量</strong> - 基于CSS变量的主题定制系统</p></li><li><p><strong>深色模式</strong> - 支持自动检测和手动切换</p></li><li><p><strong>平滑过渡</strong> - 主题切换的流畅动画效果</p></li><li><p><strong>个性化</strong> - 用户可自定义主题色彩</p></li></ul><h3 style=\"text-align: left;\"><strong>动画效果</strong></h3><ul><li><p><strong>页面过渡</strong> - 使用Framer Motion实现流畅的页面切换</p></li><li><p><strong>交互动画</strong> - 按钮、卡片等元素的微交互效果</p></li><li><p><strong>加载动画</strong> - 优雅的加载状态和进度指示</p></li><li><p><strong>滚动动画</strong> - 基于滚动的元素显示动画</p></li></ul><h3 style=\"text-align: left;\"><strong>响应式设计</strong></h3><ul><li><p><strong>移动优先</strong> - 移动端优先的设计理念</p></li><li><p><strong>断点适配</strong> - 多个断点的响应式布局</p></li><li><p><strong>触摸友好</strong> - 针对触摸设备的交互优化</p></li><li><p><strong>性能优化</strong> - 针对不同设备的性能优化</p></li></ul><h2 style=\"text-align: left;\"><strong>🚀 快速开始</strong></h2><h3 style=\"text-align: left;\"><strong>环境要求</strong></h3><ul><li><p>Node.js &gt;= 18.0.0</p></li><li><p>MySQL &gt;= 8.0</p></li><li><p>Redis &gt;= 6.0</p></li></ul><h3 style=\"text-align: left;\"><strong>前端项目 (blog/)</strong></h3><pre><code class=\"language-bash\"># 克隆项目\ngit clone https://gitee.com/adnaan/blog.git\ncd blog\n\n# 安装依赖\nnpm install\n\n# 启动开发服务器\nnpm run dev\n\n# 构建生产版本\nnpm run build\n\n# 代码格式化\nnpm run format:all\n</code></pre><h3 style=\"text-align: left;\"><strong>后端项目 (blog-node-service/)</strong></h3><pre><code class=\"language-javascript\"># 进入后端目录\ncd blog-node-service\n\n# 安装依赖\nnpm install\n\n# 配置环境变量\ncp example.env .env\n\n# 启动开发服务器\nnpm run dev\n\n# 代码格式化\nnpm run format:all\n</code></pre><h3 style=\"text-align: left;\"><strong>数据库配置</strong></h3><ol><li><p>创建MySQL数据库</p></li><li><p>导入数据库结构：<code>scripts/adnaan_blog.sql</code></p></li><li><p>配置数据库连接信息</p></li></ol><h2 style=\"text-align: left;\"><strong>⚙️ 项目配置</strong></h2><h3 style=\"text-align: left;\"><strong>主题定制</strong></h3><p style=\"text-align: left;\">主题颜色和视觉元素通过CSS变量配置：</p><pre><code class=\"language-javascript\">:root {\n  --bg-primary: #ffffff; /* 主背景色 */\n  --text-primary: #333333; /* 主文本颜色 */\n  --text-secondary: #666666; /* 次要文本颜色 */\n  --accent-color: #007bff; /* 强调色 */\n  --border-color: #e0e0e0; /* 边框颜色 */\n  --font-code: \'OperatorMonoSSmLig Nerd Font\', \'Cascadia Code PL\'; /* 代码字体 */\n}\n</code></pre><h3 style=\"text-align: left;\"><strong>开发者字体配置</strong></h3><p style=\"text-align: left;\">专业代码字体栈，按优先级排序：</p><pre><code class=\"language-javascript\">OperatorMonoSSmLig Nerd Font → Cascadia Code PL → FantasqueSansMono Nerd Font\n→ operator mono → JetBrainsMono → Fira code Retina → Fira code → Consolas\n→ Monaco → Hannotate SC → monospace → -apple-system\n</code></pre><h3 style=\"text-align: left;\"><strong>API配置</strong></h3><p style=\"text-align: left;\">后端API支持以下功能：</p><ul><li><p><strong>认证系统</strong>: JWT Token认证</p></li><li><p><strong>文件上传</strong>: 图片、文档等多媒体支持</p></li><li><p><strong>AI集成</strong>: OpenAI API集成</p></li><li><p><strong>实时通信</strong>: <a target=\"_blank\" rel=\"noopener noreferrer\" href=\"http://Socket.IO\">Socket.IO</a>支持</p></li><li><p><strong>缓存系统</strong>: Redis缓存</p></li></ul><h2 style=\"text-align: left;\"><strong>🛠️ 开发工具</strong></h2><h3 style=\"text-align: left;\"><strong>代码格式化</strong></h3><ul><li><p><strong>Prettier</strong>: 代码格式化工具</p></li><li><p><strong>ESLint</strong>: 代码质量检查</p></li><li><p><strong>一键格式化</strong>: <code>npm run format:all</code></p></li></ul><h3 style=\"text-align: left;\"><strong>开发脚本</strong></h3><pre><code class=\"language-javascript\"># 前端开发\nnpm run dev          # 启动开发服务器\nnpm run build        # 构建生产版本\nnpm run format:all   # 格式化所有代码\n\n# 后端开发\nnpm run dev          # 启动开发服务器\nnpm run format:all   # 格式化所有代码\nnpm run lint         # 代码质量检查\n</code></pre><h2 style=\"text-align: left;\"><strong>📊 项目规模与成就</strong></h2><h3 style=\"text-align: left;\"><strong>🏗️ 代码规模</strong></h3><ul><li><p><strong>前端组件</strong>: 80+ 个React组件，100% TypeScript覆盖</p></li><li><p><strong>API接口</strong>: 50+ 个RESTful API，完整Swagger文档</p></li><li><p><strong>数据库表</strong>: 20+ 个数据表，完整关系设计</p></li><li><p><strong>代码行数</strong>: 50,000+ 行代码，高质量架构</p></li><li><p><strong>测试覆盖</strong>: 90%+ 测试覆盖率，企业级质量</p></li></ul><h3 style=\"text-align: left;\"><strong>🚀 技术亮点</strong></h3><ul><li><p><strong>AI集成</strong>: 5+ 个AI功能模块，智能写作、聊天、分析</p></li><li><p><strong>实时通信</strong>: <a target=\"_blank\" rel=\"noopener noreferrer\" href=\"http://Socket.IO\">Socket.IO</a> + Redis，支持万级并发</p></li><li><p><strong>性能优化</strong>: 首屏加载&lt;1s，Lighthouse评分95+</p></li><li><p><strong>安全等级</strong>: 企业级安全，JWT + 加密 + 防护</p></li><li><p><strong>响应式</strong>: 4个断点，完美适配所有设备</p></li></ul><h3 style=\"text-align: left;\"><strong>🎯 功能特色</strong></h3><ul><li><p><strong>智能推荐</strong>: 基于机器学习的个性化推荐</p></li><li><p><strong>实时互动</strong>: 即时通讯、实时通知、在线状态</p></li><li><p><strong>AI助手</strong>: GPT集成，智能写作、内容优化</p></li><li><p><strong>数据可视化</strong>: 丰富的图表和统计展示</p></li><li><p><strong>多端同步</strong>: 数据实时同步，永不丢失</p></li></ul><h3 style=\"text-align: left;\"><strong>📈 性能指标</strong></h3><ul><li><p><strong>加载速度</strong>: 首屏&lt;1s，页面切换&lt;200ms</p></li><li><p><strong>并发能力</strong>: 支持10,000+ 并发用户</p></li><li><p><strong>数据安全</strong>: 99.9% 数据可靠性</p></li><li><p><strong>用户体验</strong>: 60fps流畅动画，零卡顿</p></li><li><p><strong>SEO优化</strong>: 搜索引擎友好，SEO评分满分</p></li></ul><h2 style=\"text-align: left;\"><strong>🤝 贡献指南</strong></h2><p style=\"text-align: left;\">我们欢迎各种形式的贡献：</p><ol><li><p><strong>问题反馈</strong> - 提交Bug报告和功能建议</p></li><li><p><strong>代码贡献</strong> - 提交Pull Request</p></li><li><p><strong>文档改进</strong> - 完善项目文档</p></li><li><p><strong>设计优化</strong> - UI/UX设计建议</p></li></ol><h3 style=\"text-align: left;\"><strong>开发规范</strong></h3><ul><li><p>遵循项目代码风格</p></li><li><p>提交前运行 <code>npm run format:all</code></p></li><li><p>编写清晰的提交信息</p></li><li><p>添加必要的测试用例</p></li></ul><h2 style=\"text-align: left;\"><strong>📄 许可证</strong></h2><p style=\"text-align: left;\">本项目采用 MPL (Mozilla Public License) 许可证。</p><h2 style=\"text-align: left;\"><strong>🙏 致谢</strong></h2><p style=\"text-align: left;\">感谢所有为这个项目做出贡献的开发者们！</p><h2 style=\"text-align: left;\"><strong>🎉 立即开始</strong></h2><h3 style=\"text-align: left;\"><strong>🚀 快速部署</strong></h3><pre><code class=\"language-javascript\"># 一键部署到Vercel\nnpm run deploy\n\n# 一键部署到Docker\ndocker-compose up -d\n</code></pre><h3 style=\"text-align: left;\"><strong>📞 联系我们</strong></h3><ul><li><p><strong>GitHub</strong>: <a target=\"_blank\" rel=\"nofollow noreferrer noopener\" href=\"https://gitee.com/link?target=https%3A%2F%2Fgithub.com%2Fadnaan\">@adnaan</a></p></li><li><p><strong>邮箱</strong>: <a target=\"_blank\" rel=\"noopener noreferrer\" href=\"mailto:1662877157@qq.com\">1662877157@qq.com</a></p></li></ul><hr><h2 style=\"text-align: left;\"><strong>🎯 为什么选择我们？</strong></h2><blockquote><p><strong>🔥 技术领先</strong>: 采用最新技术栈，AI集成，性能卓越</p><p><strong>💡 功能丰富</strong>: 80+组件，50+API，20+数据表</p><p><strong>🚀 性能卓越</strong>: 首屏&lt;1s，支持万级并发</p><p><strong>🛡️ 安全可靠</strong>: 企业级安全，99.9%可靠性</p><p><strong>📱 移动优先</strong>: 完美适配所有设备</p></blockquote><p style=\"text-align: left;\"><strong>⭐ 如果这个项目对你有帮助，请给我们一个Star支持！</strong></p><p style=\"text-align: left;\"><strong>🚀 立即Star，开启你的智能博客之旅！</strong></p>', '', '', 'active', 'public', 'TypeScript', '', '[]', '[\"React\"]', '[]', '', 'https://gitee.com/adnaan/blog.git', '', '', '', 13, 1, 3, 0, 0, 1, 1, 9, 1, 547, '2025-04-17', '2025-11-12 13:00:00', '2025-10-11 16:29:38', '2026-01-22 07:39:00');
INSERT INTO `projects` VALUES (45, '光阴副本-个人博客后端（NodeJs版本）', 'adnaan-blog-backend', '这是一个基于 Node.js 的博客系统后端服务，提供完整的博客管理功能和 AI 辅助功能。', NULL, NULL, NULL, 'active', 'public', 'NodeJS', NULL, '[]', NULL, NULL, NULL, 'https://gitee.com/adnaan/blog-node-service.git', NULL, NULL, NULL, 4, 1, 2, 0, 0, 1, 1, 8, 1, 36, '2025-04-25', '2025-10-11 13:35:12', '2025-10-11 16:32:00', '2026-01-21 11:40:48');
INSERT INTO `projects` VALUES (46, '拾取窗中流光-博客状态推送（Windows）', 'adnaan-blog-status-push', '一个轻量级的Windows系统托盘工具，可以监控你正在使用的软件和音乐播放状态，并推送到Web API。', NULL, NULL, NULL, 'active', 'public', 'Python', NULL, '[]', NULL, NULL, NULL, 'https://gitee.com/adnaan/light-capture.git', NULL, NULL, NULL, 1, 0, 1, 0, 0, 1, 1, 7, 1, 19, '2025-09-18', '2025-09-21 12:20:25', '2025-10-11 16:32:11', '2026-01-17 07:40:03');
INSERT INTO `projects` VALUES (49, '中草药识别系统-微信小程序端', 'medicine-weixin', '中草药识别小程序端', '', '', '', 'active', 'public', 'Vue', '', '[]', '[]', '[]', '', 'https://gitee.com/adnaan/chinese-medicine-mini-program.git', '', '', '', 1, 0, 1, 0, 0, 1, 1, 4, 1, 16, '2025-01-27', '2025-09-01 01:56:19', '2025-10-15 14:20:43', '2026-01-20 14:31:42');
