INSERT INTO `user_activities_archive` VALUES (21, 1, 'note_created', '发布了手记《如果活着和死亡本质无异，那便也没有存在的意义。》', '<p>我站在人潮的中央，思考日日重复的生活，我突然想，如果有一天，年轻和垂老都难以惊起心中的涟漪，一潭死水的沉闷，鲜花和蛋糕也撼动不了。</p><p>如果人开始，不能为了微小的事物而感动，那么地震和山', '/notes/8', '{\"noteId\": 8}', 5, 0, '2025-10-21 16:11:58', '2025-10-21 16:11:58');
