INSERT INTO `user_activities_archive` VALUES (26, 1, 'post_created', '发布了文章《H5连续返回重进相机变焦》', '连续返回进入获取视频流，获取的设备列表会缺少，因此在退出界面时要清除视频流占用，保证下次进入重新获取，后台设备无占用。不然会造成摄像头选择微焦镜头。', '/blog/6', '{\"postId\": 6, \"postTitle\": \"H5连续返回重进相机变焦\", \"categoryId\": 1}', 5, 0, '2025-10-29 01:46:07', '2025-10-29 01:46:07');
