INSERT INTO `user_activities_archive` VALUES (30, 1, 'note_created', '发布了手记《没去过山巅，只能看看夕阳落下屋檐。》', '<p>没去过山巅，只能看看夕阳落下屋檐。</p><p>未曾涉足深海，只能想象浪涛拍打岸边的壮阔。</p><p>生活中总有些远方，是我们未曾到达的梦。</p><p>每个人心中都有一个向往的地方，或许是山', '/notes/9', '{\"mood\": \"平静\", \"noteId\": 9}', 5, 0, '2025-10-30 16:05:05', '2025-10-30 16:05:05');
